function privatePath(path, directory = false) {
  const stat = lstatSync(path);
  if (stat.isSymbolicLink() || !(directory ? stat.isDirectory() : stat.isFile()) ||
      (stat.mode & 0o077) || (typeof process.getuid === 'function' && stat.uid !== process.getuid()))
