  identifier(source.runId,'Original reconciliation ID');
  for(const key of ['reportSha256','manifestSha256','inputManifestSha256'])check(HEX.test(source[key]),'SOURCE_IDENTITY_REQUIRED','Retain the original '+key+'.');
