    const add=value=>{result.issues.push(value);issues.push(value);};
    if(record.values&&record.targets.length===0){result.status='UNKNOWN_ROW';unknownRows++;add(issue('UNKNOWN_ROW','This row does not identify a source row in the selected handoff.',record,{rowId:result.rowId,[key]:result[key]}));}
    else if(record.values&&record.targets.some(target=>touches.get(target)>1)){
      result.status='DUPLICATE_ROW';conflictRows++;add(issue('DUPLICATE_ROW','Every repeated target is preserved from the previous revision; keep one returned row per original source.',record,{rowId:result.rowId,[key]:result[key],affectedRowIds:record.targets}));
    }else if(record.values&&record.row&&record.eventRow&&record.row.rowId===record.eventRow.rowId){
      const row=record.row,expected=protectedValues(handoff,row);
