export const PRICING_REQUEST_BYTES=Math.ceil(MAX_PRICING_REPORT_BYTES/3)*4+16_384;
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const now=()=>new Date().toISOString();
