export const CONFIG_SCHEMA = 'stellar-forge.sf104.merchant-operator.v1';
export const ORDER_SCHEMA = 'stellar-forge.sf104.merchant-order.v1';
export const REFUND_ORDER_SCHEMA = 'stellar-forge.sf104.merchant-refunds.v1';
export const INPUT_SCHEMA = 'stellar-forge.sf104.merchant-review-input.v1';
export const REVIEW_SCHEMA = 'stellar-forge.sf104.merchant-review.v1';
export const RELEASE_SCHEMA = 'stellar-forge.sf104.merchant-release.v1';
const HASH = /^[0-9a-f]{64}$/;
const REVIEW_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/;
const MAX_RESPONSE = 1024 * 1024;
const MAX_RECORD = 4 * 1024 * 1024;

export function compileOperator(raw) {
  fields(raw, ['schema', 'siteUrl', 'usernameEnv', 'applicationPasswordEnv', 'outbox', 'workspace',
    'timeoutMs', 'allowLocal'], 'WOO_OPERATOR_FIELDS_INVALID');
  need(raw.schema === CONFIG_SCHEMA, 'WOO_OPERATOR_SCHEMA_INVALID');
  need(raw.allowLocal === undefined || typeof raw.allowLocal === 'boolean', 'WOO_OPERATOR_LOCAL_OPTION_INVALID');
  let url;
  try { url = new URL(raw.siteUrl); } catch { need(false, 'WOO_OPERATOR_SITE_INVALID'); }
  const local = raw.allowLocal === true && url.protocol === 'http:' && url.hostname === '127.0.0.1' &&
    !!url.port && Number(url.port) >= 1 && Number(url.port) <= 65535;
  if (!local) url = publicUrl(raw.siteUrl, 'WOO_OPERATOR_SITE_INVALID');
  need(!url.search && !url.hash && !url.username && !url.password && !/%2f|%5c|\.\./i.test(url.pathname),
    'WOO_OPERATOR_SITE_INVALID');
  for (const name of ['usernameEnv', 'applicationPasswordEnv']) {
    need(typeof raw[name] === 'string' && /^[A-Z][A-Z0-9_]{1,80}$/.test(raw[name]), 'WOO_OPERATOR_AUTH_ENV_REQUIRED');
  }
  const timeoutMs = raw.timeoutMs ?? 15000;
  need(Number.isSafeInteger(timeoutMs) && timeoutMs >= 100 && timeoutMs <= 60000, 'WOO_OPERATOR_TIMEOUT_INVALID');
  const siteUrl = url.href.replace(/\/$/, '');
  return Object.freeze({schema:CONFIG_SCHEMA, siteUrl, usernameEnv:raw.usernameEnv,
    applicationPasswordEnv:raw.applicationPasswordEnv, outbox:absolute(raw.outbox),
    workspace:absolute(raw.workspace), timeoutMs, allowLocal:local,
    restUrl:siteUrl + '/wp-json/stellar-forge/v1/merchant/orders/'});
}

export async function loadOperator(path) { return compileOperator(await readJson(resolve(path), 65536)); }

async function responseJson(response, maxBytes = MAX_RESPONSE) {
  need(response instanceof Response && response.body && !response.redirected, 'WOO_OPERATOR_RESPONSE_INVALID');
  const reader = response.body.getReader(), chunks = []; let size = 0;
  try {
    for (;;) {
      const {value, done} = await reader.read(); if (done) break;
      size += value.byteLength; need(size <= maxBytes, 'WOO_OPERATOR_RESPONSE_TOO_LARGE'); chunks.push(value);
    }
  } catch (error) { await reader.cancel().catch(() => {}); throw error; }
  finally { reader.releaseLock(); }
  return parseJson(Buffer.concat(chunks));
}

/** Credentials are resolved only when a live WordPress read/write is selected. */
export function createMerchantClient(config, {env = process.env, fetchImpl} = {}) {
  const username = env[config.usernameEnv], password = env[config.applicationPasswordEnv];
  need(typeof username === 'string' && username.length >= 1 && username.length <= 250 &&
    !/[:\x00-\x1f\x7f]/.test(username) && typeof password === 'string' && password.length >= 1 &&
    password.length <= 1024 && !/[\x00-\x1f\x7f]/.test(password), 'WOO_OPERATOR_AUTH_REQUIRED');
  need(fetchImpl === undefined || typeof fetchImpl === 'function', 'WOO_OPERATOR_FETCH_INVALID');
  const transportFor = timeoutMs => fetchImpl ?? (config.allowLocal ? fetch : createPublicHttpsFetch({timeoutMs,
    sourceAuthorization:{origin:new URL(config.siteUrl).origin,scheme:'Basic'}}));
  const transport = transportFor(config.timeoutMs);
  const authorization = 'Basic ' + Buffer.from(username + ':' + password).toString('base64');
  const requestUrl = async (url, body, {maxBytes = MAX_RESPONSE, timeoutMs = config.timeoutMs} = {}) => {
    const selectedTransport = timeoutMs === config.timeoutMs ? transport : transportFor(timeoutMs);
    const response = await selectedTransport(url, {
      method:body ? 'POST' : 'GET', redirect:'manual', signal:AbortSignal.timeout(timeoutMs),
      headers:{authorization, accept:'application/json', ...(body ? {'content-type':'application/json'} : {})},
      ...(body ? {body:JSON.stringify(body)} : {}),
    });
    need(response.status < 300 || response.status >= 400, 'WOO_OPERATOR_REDIRECT_REFUSED');
    const value = await responseJson(response, maxBytes);
    if (response.status === 401 || response.status === 403) need(false, 'WOO_OPERATOR_AUTH_REFUSED');
    if (body) return {httpStatus:response.status, response:value};
    need(response.status === 200, safeCode(value.status, 'WOO_OPERATOR_ORDER_READ_FAILED'));
    return value;
  };
  const request = async (order, body, suffix = body ? '/release' : '', validate = validateOrder) => {
    need(reference(order), 'WOO_OPERATOR_ORDER_REQUIRED');
    const value = await requestUrl(config.restUrl + order + suffix, body);
    return body ? value : validate(value, config, order);
  };
  const consoleUrl = config.siteUrl + '/wp-json/stellar-forge/v1/merchant-console';
  const orders = async (options = {}) => {
    fields(options, ['scope', 'page', 'limit', 'state', 'sort', 'orderId'], 'WOO_QUEUE_FIELDS_INVALID');
    const scope = options.scope ?? 'checkout', page = options.page ?? 1, limit = options.limit ?? 25;
    const sort = options.sort ?? 'newest', state = options.state ?? '';
    need(['checkout', 'bound', 'notices', 'attempts'].includes(scope) &&
      Number.isSafeInteger(page) && page >= 1 && page <= 1000000 &&
      Number.isSafeInteger(limit) && limit >= 1 && limit <= 100 &&
      ['oldest', 'newest'].includes(sort) && typeof state === 'string' && /^[A-Za-z0-9_-]{0,64}$/.test(state),
      'WOO_QUEUE_SELECTION_INVALID');
    need(options.orderId === undefined || typeof options.orderId === 'string' &&
      /^[1-9][0-9]{0,17}$/.test(options.orderId) && page === 1, 'WOO_QUEUE_ORDER_SELECTION_INVALID');
    const query = new URLSearchParams({scope, page:String(page), limit:String(limit), sort, state});
    if (options.orderId !== undefined) query.set('orderId', options.orderId);
    const value = await requestUrl(consoleUrl + '/orders?' + query);
    need(object(value) && value.scope === scope && value.page === page && value.limit === limit &&
      Number.isSafeInteger(value.total) && value.total >= 0 &&
      Number.isSafeInteger(value.pages) && value.pages >= 0 && value.pages === Math.ceil(value.total / limit) &&
      Array.isArray(value.orders) && value.orders.length <= limit && value.orders.every(row =>
        object(row) && typeof row.id === 'string' && /^[1-9][0-9]{0,17}$/.test(row.id)),
      'WOO_QUEUE_RESPONSE_INVALID');
    return {schema:'stellar-forge.sf104.merchant-order-queue.v1', siteUrl:config.siteUrl, ...value,
      nextPage:value.page < value.pages ? value.page + 1 : null};
  };
  const consoleStatus = async () => {
    const value = await requestUrl(consoleUrl);
    need(object(value) && typeof value.version === 'string' && typeof value.observedAt === 'string' &&
      Array.isArray(value.health) && object(value.counts) && object(value.operator), 'WOO_CONSOLE_RESPONSE_INVALID');
    return {schema:'stellar-forge.sf104.merchant-console-status.v1', siteUrl:config.siteUrl, ...value};
  };
  return Object.freeze({
    ...createErpMethods({requestUrl,siteUrl:config.siteUrl}),
    ...createConnectorMethods({requestUrl,siteUrl:config.siteUrl}),
    consoleStatus, orders,
    inspect:order => request(order), release:(order, body) => request(order, body),
    inspectRefunds:order => request(order, undefined, '/refunds', validateRefundOrder),
    prepareRefund:(order, body) => request(order, body, '/refunds/prepare'),
    applyRefund:(order, body) => request(order, body, '/refunds/apply'),
  });
}

export function validateOrder(snapshot, config, order) {
  need(object(snapshot) && snapshot.schema === ORDER_SCHEMA && snapshot.siteUrl === config.siteUrl &&
    snapshot.orderReference === order && HASH.test(snapshot.revision) && HASH.test(snapshot.identitySha256) &&
    object(snapshot.content) && object(snapshot.content.identity) && object(snapshot.content.order), 'WOO_OPERATOR_ORDER_INVALID');
  need(snapshot.content.identity.orderReference === order, 'WOO_OPERATOR_ORDER_IDENTITY_MISMATCH');
  return snapshot;
}

/** Same authenticated transport as payment review; native bindings are checked
 * by refund-operator before a refund is prepared or applied. */
export function validateRefundOrder(snapshot, config, order) {
  need(object(snapshot) && snapshot.schema === REFUND_ORDER_SCHEMA && snapshot.siteUrl === config.siteUrl &&
    snapshot.orderReference === order && HASH.test(snapshot.revision) && HASH.test(snapshot.identitySha256) &&
    typeof snapshot.observedAt === 'string' && object(snapshot.originalPayment) && object(snapshot.order) &&
    Array.isArray(snapshot.refunds) && Array.isArray(snapshot.adjustments), 'WOO_REFUND_ORDER_INVALID');
  const money = snapshot.order;
  need(typeof money.currency === 'string' && /^[A-Z0-9]{3,12}$/.test(money.currency) &&
    Number.isSafeInteger(money.priceDecimals) && money.priceDecimals >= 0 && money.priceDecimals <= 6 &&
    ['total', 'refundedTotal', 'remainingTotal'].every(key => typeof money[key] === 'string') &&
    typeof money.status === 'string', 'WOO_REFUND_ORDER_MONEY_INVALID');
  return snapshot;
}

function recordFromOriginal(value) {
  const record = value?.schema === 'scf82.checkout-evidence.v1' ? originalRecordFromEvidence(value) : value;
  need(object(record) && object(record.requirement) && object(record.receipt), 'WOO_ORIGINAL_NATIVE_RECORD_REQUIRED');
  return record;
}

/** Both the original authenticated store notice and local native outbox must
 * identify the exact transaction, route, recipient, amount and Woo order. */
export function bindNativeSources(snapshot, nativeRow, record, payer) {
  const q = record.requirement, r = record.receipt;
  if (record.operatorReservation) checkOriginalTerms(record, payer); else checkReportedTerms(record, payer);
  need(r.success === true, 'WOO_SUCCESSFUL_NATIVE_RECEIPT_REQUIRED');
  const binding = snapshot.content.identity.binding, event = snapshot.content.event, original = nativeRow?.event;
  need(object(binding) && binding.approved === 'YES' && object(event) && HASH.test(event.id), 'WOO_ACCEPTED_BOUND_NOTICE_REQUIRED');
  need(snapshot.content.checkout?.valid !== false, 'WOO_CHECKOUT_SOURCE_CHANGED');
  need(object(original) && original.schema === OUTBOX_SCHEMA && original.id === event.id &&
    original.authority === 'ORIGINAL_NATIVE_PROCESS_SETTLEMENT_SUCCESS' &&
    original.orderReference === snapshot.orderReference && original.at === event.occurredAt,
    'WOO_NATIVE_NOTICE_SOURCE_MISMATCH');
  need(original.transactionFingerprint === digest(r.transaction), 'WOO_NATIVE_TRANSACTION_MISMATCH');
  for (const name of ['routeId', 'method', 'network', 'amountAtomic', 'assetDigest', 'recipientDigest']) {
    need(typeof binding[name] === 'string' && binding[name] === original[name], 'WOO_NATIVE_BINDING_MISMATCH');
  }
  need(binding.network === q.network && binding.amountAtomic === q.amount && binding.assetDigest === digest(q.asset) &&
    binding.recipientDigest === digest(q.payTo), 'WOO_SELECTED_NATIVE_TERMS_MISMATCH');
  need(event.id === digest(['sf98.v1', binding.routeId, binding.method, q.network, digest(r.transaction)].join('\n')),
    'WOO_TRANSACTION_EVENT_ID_MISMATCH');
  need(['RECEIVED', 'REVIEWING', 'RELEASED'].includes(event.state), 'WOO_EVENT_STATE_INVALID');
  if (event.transactionHash !== null) need(event.transactionHash === r.transaction, 'WOO_ORDER_TRANSACTION_CONFLICT');
  if (snapshot.content.order.paid) need(snapshot.content.order.transactionHash === r.transaction,
    'WOO_PAID_ORDER_TRANSACTION_CONFLICT');
  return {eventId:event.id, orderReference:snapshot.orderReference, transaction:r.transaction,
    routeId:binding.routeId, method:binding.method, network:q.network, payer, asset:q.asset,
    recipient:q.payTo, atomicAmount:q.amount, identitySha256:snapshot.identitySha256};
}

async function workspace(config, create = true) {
  const root = await privateDirectory(config.workspace, {create});
  if (create) await privateDirectory(join(root, 'reviews'));
  return root;
}
function reviewPath(config, id) {
  need(typeof id === 'string' && REVIEW_ID.test(id), 'WOO_STABLE_REVIEW_ID_REQUIRED');
  return join(config.workspace, 'reviews', id);
}
async function saveOnce(path, value) {
  try { await writeJson(path, value, {exclusive:true}); return value; }
  catch (error) { if (error.code !== 'EEXIST') throw error; return readJson(path, MAX_RECORD * 2); }
}
async function loadInput(config, id) {
  await workspace(config, false);
  const directory = await privateDirectory(reviewPath(config, id), {create:false});
  const input = await readJson(join(directory, 'input.json'), MAX_RECORD * 2);
  need(input.schema === INPUT_SCHEMA && input.reviewId === id && input.siteUrl === config.siteUrl &&
    reference(input.orderReference) && object(input.source), 'WOO_RETAINED_REVIEW_INPUT_INVALID');
  const {sha256, ...source} = input.source;
  need(HASH.test(sha256) && digest(jsonBytes(source)) === sha256, 'WOO_RETAINED_REVIEW_SOURCE_CHANGED');
  const originalBytes = await readBytes(join(directory, 'native-record.json'), MAX_RECORD);
  need(digest(originalBytes) === input.source.nativeRecordSha256, 'WOO_RETAINED_NATIVE_RECORD_CHANGED');
  const record = recordFromOriginal(parseJson(originalBytes));
  bindNativeSources(input.source.order, input.source.nativeRow, record, input.payer);
  return {directory, input, record};
}
function reviewDigest(review) {
  const {sha256, ...value} = review;
  return digest(jsonBytes(value));
}
async function loadReview(config, id) {
  const loaded = await loadInput(config, id);
  const review = await readJson(join(loaded.directory, 'review.json'), MAX_RESPONSE);
  need(review.schema === REVIEW_SCHEMA && review.reviewId === id && review.siteUrl === config.siteUrl &&
    review.sourceSha256 === loaded.input.source.sha256 && review.sha256 === reviewDigest(review),
    'WOO_RETAINED_REVIEW_CHANGED');
  return {...loaded, review};
}

export async function reviewOrder(config, {id, order, recordPath, payer, rpcEndpoint, maxEventPages = 24,
  signal, client, decodeContractEvent, fetchRpc, expectedRecordSha256} = {}) {
  need(reference(order) && typeof payer === 'string', 'WOO_ORDER_AND_TRUSTED_PAYER_REQUIRED');
  need(expectedRecordSha256 === undefined || HASH.test(expectedRecordSha256), 'WOO_REVIEW_SOURCE_HASH_REQUIRED');
  need(Number.isSafeInteger(maxEventPages) && maxEventPages >= 1 && maxEventPages <= 100, 'WOO_EVENT_PAGE_LIMIT_INVALID');
  await workspace(config);
  const directory = await privateDirectory(reviewPath(config, id));
  const inputPath = join(directory, 'input.json');
  if (!await exists(inputPath)) {
    need(typeof recordPath === 'string', 'WOO_ORIGINAL_NATIVE_RECORD_REQUIRED');
    const raw = await readBytes(absolute(recordPath), MAX_RECORD), record = recordFromOriginal(parseJson(raw));
    need(expectedRecordSha256 === undefined || digest(raw) === expectedRecordSha256, 'WOO_REVIEW_SOURCE_CHANGED');
    const observed = await (client ?? createMerchantClient(config)).inspect(order);
    await privateDirectory(config.outbox, {create:false});
    const outbox = await openOutbox(config.outbox);
    const rows = await outbox.rows();
    const nativeRow = rows.find(row => row.event.id === observed.content.event?.id);
    const binding = bindNativeSources(observed, nativeRow, record, payer);
    const source = {order:observed, nativeRow, nativeRecordSha256:digest(raw)};
    // The retained original record is written before the operation input; a
    // competing author can reuse these bytes only when the exact hash agrees.
    const nativePath = join(directory, 'native-record.json');
    try { await writeBytes(nativePath, raw, {exclusive:true}); }
    catch (error) { if (error.code !== 'EEXIST') throw error; }
    need(digest(await readBytes(nativePath, MAX_RECORD)) === source.nativeRecordSha256, 'WOO_REVIEW_ID_CONFLICT');
    await saveOnce(inputPath, {schema:INPUT_SCHEMA, reviewId:id, siteUrl:config.siteUrl,
      orderReference:order, payer, createdAt:now(), binding,
      rpcEndpoint:rpcEndpoint ?? null, maxEventPages,
      source:{...source, sha256:digest(jsonBytes(source))}});
  }
  const loaded = await loadInput(config, id), input = loaded.input;
  need(expectedRecordSha256 === undefined || input.source.nativeRecordSha256 === expectedRecordSha256,
    'WOO_REVIEW_SOURCE_CHANGED');
  need(input.orderReference === order && input.payer === payer && input.rpcEndpoint === (rpcEndpoint ?? null) &&
    input.maxEventPages === maxEventPages, 'WOO_REVIEW_ID_CONFLICT');
  if (await exists(join(directory, 'review.json'))) return (await loadReview(config, id)).review;
  const decoder = decodeContractEvent ?? await createOfficialEventDecoder();
  const options = {payer:input.payer, rpcEndpoint:input.rpcEndpoint ?? undefined,
    maxEventPages:input.maxEventPages, decodeContractEvent:decoder, signal,
    ...(fetchRpc ? {fetchImpl:fetchRpc} : {})};
  const chain = loaded.record.operatorReservation ? await reconcileRpc({...options, record:loaded.record}) :
    await reconcileReportedReceipt({...options, ...loaded.record});
  const review = {schema:REVIEW_SCHEMA, reviewId:id, siteUrl:config.siteUrl, orderReference:order,
    sourceSha256:input.source.sha256, createdAt:now(), binding:input.binding, chain,
    releasable:chain.verdict === networkProfile(chain.network).transferVerdict};
  review.sha256 = reviewDigest(review);
  await saveOnce(join(directory, 'review.json'), review);
  return (await loadReview(config, id)).review;
}

export async function resumeReview(config, id, options = {}) {
  const {input} = await loadInput(config, id);
  return reviewOrder(config, {id, order:input.orderReference, payer:input.payer,
    rpcEndpoint:input.rpcEndpoint ?? undefined, maxEventPages:input.maxEventPages, ...options});
}

const TRANSFER_FIELDS = ['schema', 'verdict', 'network', 'transaction', 'asset', 'recipient', 'payer',
  'atomicAmount', 'ledger', 'matchingTransfers', 'matchingEventId', 'rpcEndpoint'];
function releasePayload(input, review) {
  need(review.releasable === true && review.chain.verdict === networkProfile(review.binding.network).transferVerdict,
    'WOO_LIVE_NATIVE_RECONCILIATION_REQUIRED');
  need(review.chain.network === review.binding.network && review.chain.transaction === review.binding.transaction &&
    review.chain.asset === review.binding.asset && review.chain.recipient === review.binding.recipient &&
    review.chain.atomicAmount === review.binding.atomicAmount && review.chain.payer === review.binding.payer &&
    review.chain.matchingTransfers === 1, 'WOO_NATIVE_REVIEW_BINDING_MISMATCH');
  return {schema:RELEASE_SCHEMA, eventId:review.binding.eventId, transactionHash:review.binding.transaction,
    expectedRevision:input.source.order.revision, expectedIdentitySha256:input.source.order.identitySha256,
    reviewSha256:review.sha256, reviewedTransfer:Object.fromEntries(TRANSFER_FIELDS.map(key => [key, review.chain[key]])),
    confirm:'RELEASE_THIS_ORDER'};
}

function completion(snapshot, payload) {
  const event = snapshot.content.event, order = snapshot.content.order, native = snapshot.nativeReview;
  return event?.id === payload.eventId && event.state === 'RELEASED' && event.transactionHash === payload.transactionHash &&
    order.paid === true && order.transactionHash === payload.transactionHash &&
    native?.reviewSha256 === payload.reviewSha256 && native?.eventId === payload.eventId &&
    native?.transactionHash === payload.transactionHash;
}

export async function releaseOrder(config, id, {confirmOrder, client, expectedReviewSha256} = {}) {
  const {directory, input, review} = await loadReview(config, id);
  need(confirmOrder === review.orderReference, 'WOO_EXPLICIT_ORDER_CONFIRMATION_REQUIRED');
  need(expectedReviewSha256 === undefined || HASH.test(expectedReviewSha256) && review.sha256 === expectedReviewSha256,
    'WOO_RETAINED_REVIEW_CHANGED');
  const payload = releasePayload(input, review), api = client ?? createMerchantClient(config);
  const before = await api.inspect(review.orderReference);
  if (completion(before, payload)) return {schema:RELEASE_SCHEMA, status:'RELEASE_CONFIRMED',
    reviewId:id, reviewSha256:review.sha256, orderReference:review.orderReference, order:before};
  need(before.identitySha256 === payload.expectedIdentitySha256, 'WOO_REVIEW_SOURCE_CHANGED');
  const recovery = ['REVIEWING', 'RELEASED'].includes(before.content.event?.state) &&
    before.content.event.transactionHash === payload.transactionHash;
  need(recovery || before.revision === payload.expectedRevision, 'WOO_REVIEW_SOURCE_CHANGED');
  const attemptId = randomUUID(), attemptFile = join(directory, 'release-' + attemptId + '.json');
  let attempt = {schema:RELEASE_SCHEMA, attemptId, reviewId:id, reviewSha256:review.sha256,
    orderReference:review.orderReference, startedAt:now(), status:'DISPATCH_RECORDED', payload};
  await writeJson(attemptFile, attempt, {exclusive:true});
  let response;
  try { response = await api.release(review.orderReference, payload); }
  catch (error) { attempt.error = safeCode(error.code, 'WOO_RELEASE_RESPONSE_UNAVAILABLE'); }
  let observed;
  try { observed = await api.inspect(review.orderReference); }
  catch (error) { attempt.readbackError = safeCode(error.code, 'WOO_RELEASE_READBACK_UNAVAILABLE'); }
  attempt = {...attempt, completedAt:now(), response:response ?? null, order:observed ?? null,
    status:observed && completion(observed, payload) ? 'RELEASE_CONFIRMED' :
      response ? safeCode(response.response?.status, 'RELEASE_REOPEN_REQUIRED') : 'RELEASE_OUTCOME_UNKNOWN'};
  await writeJson(attemptFile, attempt);
  return attempt;
}

export async function inspectReview(config, id, {live = false, client} = {}) {
  const {directory, input} = await loadInput(config, id);
  const review = await exists(join(directory, 'review.json')) ? (await loadReview(config, id)).review : null;
  const names = (await readdir(directory)).filter(name => /^release-[0-9a-f-]{36}\.json$/.test(name));
  const attempts = await Promise.all(names.map(name => readJson(join(directory, name), MAX_RESPONSE * 2)));
  attempts.sort((a, b) => a.startedAt.localeCompare(b.startedAt) || a.attemptId.localeCompare(b.attemptId));
  const observed = live ? await (client ?? createMerchantClient(config)).inspect(input.orderReference) : null;
  return {schema:'stellar-forge.sf104.merchant-review-status.v1', reviewId:id,
    siteUrl:config.siteUrl, orderReference:input.orderReference,
    status:review ? 'REVIEW_COMPLETE' : 'REVIEW_PREPARED', input, review, attempts,
    ...(observed ? {order:observed} : {})};
}

export async function listReviews(config) {
  await workspace(config, false);
  const names = (await readdir(join(config.workspace, 'reviews'), {withFileTypes:true}))
    .filter(entry => entry.isDirectory() && REVIEW_ID.test(entry.name)).map(entry => entry.name).sort();
  return Promise.all(names.map(async id => {
    try {
      const value = await inspectReview(config, id);
      return {reviewId:id, orderReference:value.orderReference, status:value.status,
        verdict:value.review?.chain.verdict ?? null, transaction:value.review?.binding.transaction ?? null,
        lastRelease:value.attempts.at(-1)?.status ?? null};
    } catch (error) { return {reviewId:id, status:'REVIEW_UNAVAILABLE', error:safeCode(error.code, 'WOO_REVIEW_READ_FAILED')}; }
  }));
}

export async function exportReview(config, id, destination) {
  const {directory} = await loadInput(config, id);
  const status = await inspectReview(config, id);
  const target = await privateDirectory(absolute(destination));
  need(target !== directory && !target.startsWith(directory + '/'), 'WOO_EXPORT_OUTSIDE_REVIEW_REQUIRED');
  const names = ['input.json', 'native-record.json', ...(status.review ? ['review.json'] : []),
    ...status.attempts.map(attempt => 'release-' + attempt.attemptId + '.json')];
  const files = [];
  for (const name of names) {
    const bytes = await readBytes(join(directory, name), MAX_RECORD * 2);
    try { await writeBytes(join(target, name), bytes, {exclusive:true}); }
    catch (error) { if (error.code !== 'EEXIST') throw error; }
    need(digest(await readBytes(join(target, name), MAX_RECORD * 2)) === digest(bytes), 'WOO_EXPORT_FILE_CONFLICT');
    files.push({name, bytes:bytes.length, sha256:digest(bytes)});
  }
  const manifest = {schema:'stellar-forge.sf104.merchant-review-export.v1', reviewId:id,
    siteUrl:config.siteUrl, orderReference:status.orderReference, files};
  const saved = await saveOnce(join(target, 'manifest.json'), manifest);
  need(JSON.stringify(saved) === JSON.stringify(manifest), 'WOO_EXPORT_MANIFEST_CONFLICT');
  return {...manifest, directory:target};
}

// MIT. Receive an original verified Woo refund handoff into the operator workspace.
import {constants} from 'node:fs';
import {open, lstat, readdir, link, unlink, rm} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
import {join, dirname, sep} from 'node:path';
import {reference} from './buyer.mjs';
import {inspectRefund} from './refund-operator.mjs';
import {adjustmentId} from '../merchant-settlement-accounting/adjustments.mjs';
import {absolute, need, object, digest, now, privateDirectory, parseJson,
  jsonBytes, exists, syncDirectory} from '../sf88-operator-buyer-cli/node/store.mjs';

export const REFUND_HANDOFF_SCHEMA = 'stellar-forge.sf104.merchant-refund-export.v1';
export const REFUND_RECEIVE_SCHEMA = 'stellar-forge.sf104.merchant-refund-receive.v1';
export const REFUND_HANDOFF_LIMITS = Object.freeze({
  files:2048, bytes:256 * 1024 * 1024, manifestBytes:1024 * 1024,
  adjustmentBytes:32 * 1024 * 1024, stateBytes:4 * 1024 * 1024,
});
const HASH = /^[a-f0-9]{64}$/;
const REQUIRED = ['adjustments.json', 'adjustment-request.json', 'order-before.json', 'input.json'];
const RECORD = /^(?:prepare|apply|recover)-[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}\.json$/;
const REVIEW = /^review-[a-f0-9]{64}\.json$/;
const MANIFEST_KEYS = ['adjustmentId', 'files', 'inputSha256', 'orderReference', 'schema', 'siteUrl'];
const entryLimit = name => name === 'adjustments.json' ?
  REFUND_HANDOFF_LIMITS.adjustmentBytes : REFUND_HANDOFF_LIMITS.stateBytes;
const related = (a, b) => a === b || a.startsWith(b + sep) || b.startsWith(a + sep);

function exactFields(value, keys, code) {
  need(object(value) && Object.keys(value).sort().join('\n') === [...keys].sort().join('\n'), code);
}

/** Delivered files stay single-link; only exact receiver-owned temporary aliases can recover. */
async function snapshotFile(path, {bytes, sha256, limit, receiverCopy = false}) {
  const named = await lstat(absolute(path));
  need(named.isFile() && !named.isSymbolicLink() &&
    (receiverCopy ? named.nlink >= 1 : named.nlink === 1), 'WOO_REFUND_HANDOFF_FILE_INVALID');
  const handle = await open(absolute(path), constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const before = await handle.stat();
    need(before.dev === named.dev && before.ino === named.ino, 'WOO_REFUND_HANDOFF_FILE_CHANGED');
    need(before.isFile() && Number.isSafeInteger(before.size) && before.size > 0 && before.size <= limit &&
      (bytes === undefined || before.size === bytes), 'WOO_REFUND_HANDOFF_FILE_INVALID');
    const raw = Buffer.alloc(before.size);
    let offset = 0;
    while (offset < raw.length) {
      const read = await handle.read(raw, offset, Math.min(65536, raw.length - offset), offset);
      need(read.bytesRead > 0, 'WOO_REFUND_HANDOFF_FILE_CHANGED');
      offset += read.bytesRead;
    }
    const extra = await handle.read(Buffer.alloc(1), 0, 1, raw.length), after = await handle.stat();
    const currentName = await lstat(path), actualHash = digest(raw);
    need(extra.bytesRead === 0 && after.size === before.size && after.nlink === before.nlink &&
      after.mtimeMs === before.mtimeMs && after.ctimeMs === before.ctimeMs &&
      currentName.dev === before.dev && currentName.ino === before.ino && !currentName.isSymbolicLink() &&
      (sha256 === undefined || actualHash === sha256), 'WOO_REFUND_HANDOFF_FILE_CHANGED');
    if (receiverCopy && after.nlink > 1) {
      // A killed exclusive copy may have linked its completed file but not yet
      // removed its private temporary name. Retire only this receiver's aliases
      // of the exact verified inode; an unrelated external hard link still fails.
      const prefix = '.sf104-receive-' + actualHash + '-';
      for (const name of await readdir(dirname(path))) {
        if (!name.startsWith(prefix) || !/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/.test(name.slice(prefix.length))) continue;
        const candidate = join(dirname(path), name);
        let alias;
        try { alias = await lstat(candidate); } catch (error) { if (error.code === 'ENOENT') continue; throw error; }
        if (alias.isFile() && !alias.isSymbolicLink() && alias.dev === before.dev && alias.ino === before.ino)
          await unlink(candidate).catch(error => { if (error.code !== 'ENOENT') throw error; });
      }
      need((await handle.stat()).nlink === 1, 'WOO_REFUND_HANDOFF_FILE_INVALID');
      await syncDirectory(dirname(path));
    } else need(after.nlink === 1, 'WOO_REFUND_HANDOFF_FILE_INVALID');
    return raw;
  } finally { await handle.close(); }
}

/** Publish one complete file exclusively; its recoverable temporary stays in this private directory. */
async function writeFirst(path, raw) {
  const temporary = join(dirname(path), '.sf104-receive-' + digest(raw) + '-' + randomUUID());
  let handle;
  try {
    handle = await open(temporary, 'wx', 0o600);
    await handle.writeFile(raw); await handle.sync(); await handle.close(); handle = undefined;
    await link(temporary, path);
  } finally {
    if (handle) await handle.close();
    await unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; });
  }
  await syncDirectory(dirname(path));
}

async function retainFile(path, raw, descriptor) {
  if (!await exists(path)) {
    try { await writeFirst(path, raw); }
    catch (error) { if (error.code !== 'EEXIST') throw error; }
  }
  await snapshotFile(path, {...descriptor, limit:descriptor.bytes, receiverCopy:true});
}

function manifestFrom(raw, config) {
  const value = parseJson(raw);
  exactFields(value, MANIFEST_KEYS, 'WOO_REFUND_HANDOFF_MANIFEST_INVALID');
  need(value.schema === REFUND_HANDOFF_SCHEMA, 'WOO_REFUND_HANDOFF_MANIFEST_REQUIRED');
  adjustmentId(value.adjustmentId);
  need(value.siteUrl === config.siteUrl && reference(value.orderReference) &&
    HASH.test(value.inputSha256), 'WOO_REFUND_HANDOFF_STORE_OR_ORDER_CHANGED');
  need(Array.isArray(value.files) && value.files.length >= REQUIRED.length &&
    value.files.length <= REFUND_HANDOFF_LIMITS.files, 'WOO_REFUND_HANDOFF_FILE_LIMIT');
  let total = 0; const names = new Set();
  for (const file of value.files) {
    exactFields(file, ['name', 'bytes', 'sha256'], 'WOO_REFUND_HANDOFF_ENTRY_INVALID');
    need(typeof file.name === 'string' && (REQUIRED.includes(file.name) ||
      RECORD.test(file.name) || REVIEW.test(file.name)) && !names.has(file.name) &&
      Number.isSafeInteger(file.bytes) && file.bytes > 0 && file.bytes <= entryLimit(file.name) &&
      typeof file.sha256 === 'string' && HASH.test(file.sha256), 'WOO_REFUND_HANDOFF_ENTRY_INVALID');
    names.add(file.name); total += file.bytes;
    need(total <= REFUND_HANDOFF_LIMITS.bytes, 'WOO_REFUND_HANDOFF_BYTE_LIMIT');
  }
  need(REQUIRED.every(name => names.has(name)), 'WOO_REFUND_HANDOFF_INPUT_MISSING');
  return {manifest:value, total};
}

function summary(manifest, state, sha256, total) {
  need(state.adjustmentId === manifest.adjustmentId && state.siteUrl === manifest.siteUrl &&
    state.orderReference === manifest.orderReference && state.input.sha256 === manifest.inputSha256,
    'WOO_REFUND_HANDOFF_INPUT_CHANGED');
  return {schema:REFUND_RECEIVE_SCHEMA, adjustmentId:manifest.adjustmentId,
    orderReference:manifest.orderReference, siteUrl:manifest.siteUrl,
    manifestSha256:sha256, inputSha256:manifest.inputSha256,
    operationStatus:state.status, amountAtomic:state.input.amountAtomic,
    wooAmount:state.input.wooAmount, currency:state.input.currency,
    originalTransactionHash:state.input.originalTransactionHash,
    refundTransactionHash:state.input.reviewedRefund.transaction,
    reviews:state.reviews.length, attempts:state.attempts.length,
    files:manifest.files.length, bytes:total};
}

function sealed(value) { return {...value, sha256:digest(jsonBytes(value))}; }
function readReceipt(raw, expected) {
  const value = parseJson(raw);
  need(object(value), 'WOO_REFUND_RECEIVE_RECEIPT_CHANGED');
  const {sha256, ...body} = value;
  need(HASH.test(sha256) && digest(jsonBytes(body)) === sha256 &&
    value.schema === REFUND_RECEIVE_SCHEMA && value.status === 'RECEIVED' &&
    value.manifestSha256 === expected.manifestSha256 &&
    value.inputSha256 === expected.inputSha256 &&
    value.adjustmentId === expected.adjustmentId &&
    value.orderReference === expected.orderReference && value.siteUrl === expected.siteUrl &&
    value.workspace === expected.workspace, 'WOO_REFUND_RECEIVE_RECEIPT_CHANGED');
  return value;
}

async function completedReceipt(config, manifest, manifestSha256, total, workspace, target) {
  const directory = join(workspace, 'refund-handoffs', manifest.adjustmentId, manifestSha256);
  const path = join(directory, 'receipt.json');
  if (!await exists(path)) return null;
  for (const parent of [join(workspace, 'refund-handoffs'),
    join(workspace, 'refund-handoffs', manifest.adjustmentId), directory,
    join(workspace, 'refunds'), target]) await privateDirectory(parent, {create:false});
  const raw = await snapshotFile(path, {limit:REFUND_HANDOFF_LIMITS.manifestBytes, receiverCopy:true});
  const expected = {manifestSha256, inputSha256:manifest.inputSha256,
    adjustmentId:manifest.adjustmentId, orderReference:manifest.orderReference, siteUrl:manifest.siteUrl, workspace};
  const receipt = readReceipt(raw, expected);
  for (const file of manifest.files)
    await snapshotFile(join(target, file.name), {...file, limit:entryLimit(file.name), receiverCopy:true});
  const current = await inspectRefund(config, manifest.adjustmentId);
  summary(manifest, current, manifestSha256, total);
  return receipt;
}

/**
 * Validate the complete original export, then copy its original files without
 * replacing any retained record. The existing refund engine validates the
 * native source, input seal, reviews and attempt bindings in an isolated stage.
 * check:true returns that reviewed snapshot before installing the operation.
 */
export async function receiveRefund(config, sourceDirectory, {expectedManifestSha256, check = false} = {}) {
  need(typeof expectedManifestSha256 === 'string' && HASH.test(expectedManifestSha256),
    'WOO_REFUND_HANDOFF_HASH_REQUIRED');
  need(typeof check === 'boolean', 'WOO_REFUND_HANDOFF_CHECK_INVALID');
  const source = await privateDirectory(absolute(sourceDirectory), {create:false});
  const manifestRaw = await snapshotFile(join(source, 'manifest.json'),
    {sha256:expectedManifestSha256, limit:REFUND_HANDOFF_LIMITS.manifestBytes});
  const {manifest, total} = manifestFrom(manifestRaw, config);
  const names = new Set(['manifest.json', ...manifest.files.map(file => file.name)]);
  const entries = await readdir(source, {withFileTypes:true});
  need(entries.length === names.size && entries.every(entry => names.has(entry.name) && entry.isFile()),
    'WOO_REFUND_HANDOFF_FILE_SET_CHANGED');
  const workspace = await privateDirectory(config.workspace);
  const targetParent = join(workspace, 'refunds'), target = join(targetParent, manifest.adjustmentId);
  const stageParent = join(workspace, '.refund-receive');
  const stage = join(stageParent, manifest.adjustmentId + '-' + expectedManifestSha256);
  need(!related(source, target) && !related(source, stage), 'WOO_REFUND_HANDOFF_SEPARATE_DIRECTORY_REQUIRED');
  if (!check) {
    const completed = await completedReceipt(config, manifest, expectedManifestSha256, total, workspace, target);
    if (completed) return completed;
  }
  await privateDirectory(stageParent);
  await privateDirectory(stage);
  const claim = jsonBytes({schema:REFUND_RECEIVE_SCHEMA, adjustmentId:manifest.adjustmentId,
    siteUrl:manifest.siteUrl, workspace, manifestSha256:expectedManifestSha256});
  await retainFile(join(stage, 'claim.json'), claim, {bytes:claim.length, sha256:digest(claim)});
  await retainFile(join(stage, 'manifest.json'), manifestRaw,
    {bytes:manifestRaw.length, sha256:expectedManifestSha256});
  await privateDirectory(join(stage, 'refunds'));
  const stagedOperation = await privateDirectory(join(stage, 'refunds', manifest.adjustmentId));
  // A copy is restartable at each immutable file. Always recheck the source.
  for (const file of manifest.files) {
    const raw = await snapshotFile(join(source, file.name), {...file, limit:entryLimit(file.name)});
    await retainFile(join(stagedOperation, file.name), raw, file);
  }
  const original = await inspectRefund({...config, workspace:stage}, manifest.adjustmentId);
  const reviewed = summary(manifest, original, expectedManifestSha256, total);
  if (check) return {...reviewed, status:'REVIEWED', workspace, operationDirectory:target};

  // Preflight every existing named record before copying any new target file.
  // Later local attempts may coexist; delivered attempts can never replace them.
  await privateDirectory(targetParent);
  await privateDirectory(target);
  for (const file of manifest.files) {
    const path = join(target, file.name);
    if (await exists(path)) await snapshotFile(path, {...file, limit:entryLimit(file.name), receiverCopy:true});
  }
  // A new operation becomes readable only after all of its source/history files.
  const ordered = [...manifest.files].sort((a, b) =>
    Number(a.name === 'input.json') - Number(b.name === 'input.json') || a.name.localeCompare(b.name));
  for (const file of ordered) {
    const raw = await snapshotFile(join(stagedOperation, file.name), {...file, limit:entryLimit(file.name), receiverCopy:true});
    await retainFile(join(target, file.name), raw, file);
  }
  const received = await inspectRefund(config, manifest.adjustmentId);
  summary(manifest, received, expectedManifestSha256, total);

  const receipts = await privateDirectory(join(workspace, 'refund-handoffs'));
  const byAdjustment = await privateDirectory(join(receipts, manifest.adjustmentId));
  const receiptDirectory = await privateDirectory(join(byAdjustment, expectedManifestSha256));
  await retainFile(join(receiptDirectory, 'manifest.json'), manifestRaw,
    {bytes:manifestRaw.length, sha256:expectedManifestSha256});
  const receiptPath = join(receiptDirectory, 'receipt.json');
  const receipt = sealed({...reviewed, status:'RECEIVED', receivedAt:now(), workspace,
    operationDirectory:target, receiptDirectory});
  try { await writeFirst(receiptPath, jsonBytes(receipt)); }
  catch (error) { if (error.code !== 'EEXIST') throw error; }
  const saved = readReceipt(await snapshotFile(receiptPath, {limit:REFUND_HANDOFF_LIMITS.manifestBytes, receiverCopy:true}),
    {...reviewed, workspace});
  // This exact stage is owned by the validated claim and is now fully copied.
  await snapshotFile(join(stage, 'claim.json'), {bytes:claim.length, sha256:digest(claim), limit:claim.length, receiverCopy:true});
  await rm(stage, {recursive:true, force:true}).catch(() => {});
  return saved;
}

// MIT. Record verified merchant refunds in the original WooCommerce order.
import {randomUUID} from 'node:crypto';
import {readdir} from 'node:fs/promises';
import {join, sep} from 'node:path';
import {reference} from './buyer.mjs';
import {createMerchantClient, validateRefundOrder} from './merchant-operator.mjs';
import {networkProfile, checkMerchantRefundTerms} from '../sf86-rpc-transfer-reconcile/terms.mjs';
import {ADJUSTMENT_EXPORT_SCHEMA, adjustmentId, adjustmentAmount, adjustmentInstant,
  adjustmentEventIdentity, adjustmentRequest, adjustmentJson, validateAdjustment,
  validateRefundProof} from '../merchant-settlement-accounting/adjustments.mjs';
import {absolute, need, object, digest, now, privateDirectory, readBytes, readJson,
  parseJson, writeBytes, writeJson, exists, jsonBytes, safeCode} from '../sf88-operator-buyer-cli/node/store.mjs';

export const REFUND_SCHEMA = 'stellar-forge.sf104.merchant-refund.v1';
export const REFUND_INPUT_SCHEMA = 'stellar-forge.sf104.merchant-refund-input.v1';
export const REFUND_REVIEW_SCHEMA = 'stellar-forge.sf104.merchant-refund-review.v1';
export const REFUND_STATUS_SCHEMA = 'stellar-forge.sf104.merchant-refund-status.v1';
const HASH = /^[0-9a-f]{64}$/;
const UUID = /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/;
const MAX_EXPORT = 32 * 1024 * 1024;
const MAX_STATE = 4 * 1024 * 1024;
const ATTEMPT = /^(prepare|apply|recover)-[a-f0-9-]{36}\.json$/;
const REVIEW = /^review-[a-f0-9]{64}\.json$/;
const nativeId = value => typeof value === 'string' ? /^[1-9][0-9]{0,17}$/.test(value) :
  Number.isSafeInteger(value) && value > 0;

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (object(value)) return Object.fromEntries(Object.keys(value).sort().map(key => [key, stable(value[key])]));
  return value;
}
const same = (left, right) => JSON.stringify(stable(left)) === JSON.stringify(stable(right));
function sealed(value) { return {...value, sha256:digest(jsonBytes(value))}; }
function validSeal(value, code) {
  const {sha256, ...body} = value;
  need(HASH.test(sha256) && digest(jsonBytes(body)) === sha256, code);
  return value;
}

/** Parse store currency without binary floating point or an implied FX rate. */
export function wooMoney(value, decimals, {positive = false} = {}) {
  need(Number.isSafeInteger(decimals) && decimals >= 0 && decimals <= 6 &&
    typeof value === 'string' && /^(0|[1-9][0-9]{0,11})(?:\.[0-9]+)?$/.test(value),
    'WOO_REFUND_AMOUNT_INVALID');
  const [whole, fraction = ''] = value.split('.');
  need(fraction.length <= decimals, 'WOO_REFUND_AMOUNT_PRECISION');
  const units = BigInt(whole) * 10n ** BigInt(decimals) + BigInt(fraction.padEnd(decimals, '0') || '0');
  need(units <= 9007199254740991n, 'WOO_REFUND_AMOUNT_TOO_LARGE');
  need(!positive || units > 0n, 'WOO_REFUND_POSITIVE_AMOUNT_REQUIRED');
  return {units, amount:whole + (decimals ? '.' + fraction.padEnd(decimals, '0') : '')};
}

function originalIdentity(event) {
  return {...adjustmentEventIdentity(event), routeId:event.routeId ?? null, method:event.method ?? null,
    orderReferenceDigest:event.orderReferenceDigest ?? null};
}

/** Select exactly one verified adjustment from the unmodified accounting export. */
export function selectRefundAdjustment(value, id) {
  adjustmentId(id);
  need(object(value) && value.schema === ADJUSTMENT_EXPORT_SCHEMA && object(value.source) &&
    Array.isArray(value.events) && value.events.length <= 5000 &&
    object(value.originalReport) && Array.isArray(value.originalReport.ledger),
    'WOO_ORIGINAL_ADJUSTMENT_EXPORT_REQUIRED');
  adjustmentInstant(value.exportedAt, 'export date');
  const found = [], seen = new Set(); let count = 0;
  for (const event of value.events) {
    need(object(event) && object(event.original) && Array.isArray(event.adjustments), 'WOO_ADJUSTMENT_EXPORT_INVALID');
    for (const record of event.adjustments) {
      need(object(record) && ++count <= 5000 && !seen.has(record.id), 'WOO_DUPLICATE_ADJUSTMENT');
      seen.add(record.id);
      if (record.id === id) found.push({event, record});
    }
  }
  need(found.length === 1, 'WOO_REFUND_ADJUSTMENT_NOT_FOUND');
  const {event, record} = found[0];
  validateAdjustment(record);
  need(record.kind === 'REFUND' && record.status === 'VERIFIED', 'WOO_VERIFIED_REFUND_REQUIRED');
  validateRefundProof(record.verification.proof, record);
  for (const key of ['runId', 'reportSha256', 'inputManifestSha256']) {
    need(value.source[key] === record.source[key], 'WOO_REFUND_EXPORT_SOURCE_MISMATCH');
  }
  need(same(originalIdentity(event.original), originalIdentity(record.original)), 'WOO_REFUND_ORIGINAL_EVENT_CHANGED');
  const originals = value.originalReport.ledger.filter(row =>
    row.eventId === record.eventId && row.network === record.original.network);
  need(originals.length === 1 && same(originalIdentity(originals[0]), originalIdentity(record.original)),
    'WOO_REFUND_ORIGINAL_REPORT_CHANGED');
  return {record, event:event.original};
}

/** Bind the selected accounting row to the exact released Woo payment and its
 * original native payer, then require the canonical reverse-transfer proof. */
export function bindRefundAdjustment(value, id, snapshot, config, order) {
  validateRefundOrder(snapshot, config, order);
  const selected = selectRefundAdjustment(value, id), record = selected.record;
  const original = record.original, payment = snapshot.originalPayment;
  const binding = payment.binding, transfer = payment.reviewedTransfer, proof = record.verification.proof;
  need(payment.state === 'RELEASED' && HASH.test(payment.eventId) && HASH.test(payment.transactionHash) &&
    object(binding) && binding.approved === 'YES' && object(transfer), 'WOO_RELEASED_NATIVE_PAYMENT_REQUIRED');
  need(original.eventId === payment.eventId && record.eventId === payment.eventId &&
    original.routeId === binding.routeId && original.method === binding.method &&
    snapshot.order.transactionHash === payment.transactionHash && original.orderReferenceDigest === digest(order) &&
    original.transactionFingerprint === digest(payment.transactionHash),
    'WOO_REFUND_ORIGINAL_PAYMENT_MISMATCH');
  const identity = originalIdentity(original), profile = networkProfile(binding.network);
  need(identity.network === binding.network && identity.amountAtomic === binding.amountAtomic &&
    identity.assetDigest === binding.assetDigest && identity.recipientDigest === binding.recipientDigest,
    'WOO_REFUND_ORIGINAL_TERMS_MISMATCH');
  need(typeof binding.routeId === 'string' && typeof binding.method === 'string' &&
    payment.eventId === digest(['sf98.v1', binding.routeId, binding.method, binding.network,
      digest(payment.transactionHash)].join('\n')), 'WOO_REFUND_EVENT_ID_MISMATCH');
  need(transfer.verdict === profile.transferVerdict && transfer.matchingTransfers === 1 &&
    transfer.network === binding.network && transfer.transaction === payment.transactionHash &&
    transfer.atomicAmount === binding.amountAtomic && typeof transfer.asset === 'string' &&
    typeof transfer.recipient === 'string' && typeof transfer.payer === 'string' &&
    digest(transfer.asset) === binding.assetDigest && digest(transfer.recipient) === binding.recipientDigest,
    'WOO_REFUND_ORIGINAL_REVIEW_MISMATCH');
  need(record.refundTerms.network === transfer.network && record.refundTerms.asset === transfer.asset &&
    record.refundTerms.from === transfer.recipient && record.refundTerms.to === transfer.payer &&
    proof.transaction !== payment.transactionHash, 'WOO_REFUND_REVERSE_IDENTITY_MISMATCH');
  checkMerchantRefundTerms({refundId:id, network:proof.network, asset:proof.asset, payer:proof.payer,
    recipient:proof.recipient, atomicAmount:proof.atomicAmount, transaction:proof.transaction});
  need(BigInt(adjustmentAmount(record.amountAtomic)) <= BigInt(adjustmentAmount(binding.amountAtomic)),
    'WOO_REFUND_EXCEEDS_ORIGINAL_PAYMENT');
  return selected;
}

async function workspace(config, create = true) {
  const root = await privateDirectory(config.workspace, {create});
  return privateDirectory(join(root, 'refunds'), {create});
}
function refundPath(config, id) { return join(config.workspace, 'refunds', adjustmentId(id)); }
async function retainBytes(path, bytes, limit = MAX_STATE) {
  try { await writeBytes(path, bytes, {exclusive:true}); }
  catch (error) { if (error.code !== 'EEXIST') throw error; }
  need(digest(await readBytes(path, limit)) === digest(bytes), 'WOO_REFUND_RETAINED_FILE_CONFLICT');
}
async function saveFirst(path, value) {
  try { await writeJson(path, value, {exclusive:true}); return value; }
  catch (error) { if (error.code !== 'EEXIST') throw error; return readJson(path, MAX_STATE); }
}

async function loadInput(config, id) {
  await workspace(config, false);
  const directory = await privateDirectory(refundPath(config, id), {create:false});
  const input = validSeal(await readJson(join(directory, 'input.json'), MAX_STATE), 'WOO_REFUND_INPUT_CHANGED');
  need(input.schema === REFUND_INPUT_SCHEMA && input.adjustmentId === id && input.siteUrl === config.siteUrl &&
    reference(input.orderReference), 'WOO_REFUND_INPUT_INVALID');
  const raw = await readBytes(join(directory, 'adjustments.json'), MAX_EXPORT);
  const beforeRaw = await readBytes(join(directory, 'order-before.json'), MAX_STATE);
  const request = await readBytes(join(directory, 'adjustment-request.json'), MAX_STATE);
  need(digest(raw) === input.sourceSha256 && digest(beforeRaw) === input.originalSnapshotSha256 &&
    digest(request) === input.requestSha256, 'WOO_REFUND_SOURCE_CHANGED');
  const exported = parseJson(raw), before = parseJson(beforeRaw);
  const {record} = bindRefundAdjustment(exported, id, before, config, input.orderReference);
  need(digest(adjustmentJson(adjustmentRequest(record))) === input.requestSha256 &&
    before.identitySha256 === input.identitySha256 && before.originalPayment.eventId === input.eventId &&
    before.originalPayment.transactionHash === input.originalTransactionHash &&
    input.amountAtomic === record.amountAtomic && input.reason === record.reason &&
    same(input.reviewedRefund, record.verification.proof) &&
    input.currency === before.order.currency && input.priceDecimals === before.order.priceDecimals,
    'WOO_REFUND_INPUT_BINDING_CHANGED');
  need(wooMoney(input.wooAmount, input.priceDecimals, {positive:true}).amount === input.wooAmount,
    'WOO_REFUND_INPUT_AMOUNT_CHANGED');
  return {directory, input, exported, record};
}

function payload(input, revision) {
  return {schema:REFUND_SCHEMA, adjustmentId:input.adjustmentId, eventId:input.eventId,
    originalTransactionHash:input.originalTransactionHash, expectedIdentitySha256:input.identitySha256,
    expectedRevision:revision, sourceSha256:input.sourceSha256, requestSha256:input.requestSha256,
    amountAtomic:input.amountAtomic, wooAmount:input.wooAmount, currency:input.currency,
    reason:input.reason, reviewedRefund:input.reviewedRefund, confirm:'PREPARE_THIS_REFUND'};
}

function inspectMapping(config, loaded, snapshot) {
  const {input, exported} = loaded;
  bindRefundAdjustment(exported, input.adjustmentId, snapshot, config, input.orderReference);
  need(snapshot.identitySha256 === input.identitySha256 && snapshot.order.currency === input.currency &&
    snapshot.order.priceDecimals === input.priceDecimals, 'WOO_REFUND_ORDER_CHANGED');
  const rows = snapshot.adjustments.filter(row => row?.adjustmentId === input.adjustmentId);
  need(rows.length <= 1, 'WOO_REFUND_DUPLICATE_MAPPING');
  if (!rows.length) return {status:'NOT_PREPARED', adjustment:null, refund:null};
  const row = rows[0];
  for (const key of ['adjustmentId', 'eventId', 'originalTransactionHash', 'sourceSha256', 'requestSha256',
    'amountAtomic', 'currency', 'reason']) {
    need(row[key] === input[key], 'WOO_REFUND_MAPPING_CHANGED');
  }
  need(HASH.test(row.reviewSha256) && row.orderReference === input.orderReference &&
    row.transactionHash === input.reviewedRefund.transaction && row.network === input.reviewedRefund.network &&
    wooMoney(row.wooAmount, input.priceDecimals, {positive:true}).amount === input.wooAmount &&
    same(row.reviewedRefund, input.reviewedRefund), 'WOO_REFUND_MAPPING_CHANGED');
  const children = snapshot.refunds.filter(refund => refund?.adjustmentId === input.adjustmentId);
  const child = children.length === 1 ? children[0] : null;
  const exact = child && nativeId(child.id) &&
    child.reviewSha256 === row.reviewSha256 && child.transactionHash === row.transactionHash &&
    child.currency === input.currency &&
    wooMoney(child.amount, input.priceDecimals, {positive:true}).amount === input.wooAmount;
  if (children.length > 1 || (children.length && !exact)) {
    return {status:'REFUND_RECONCILIATION_REQUIRED', adjustment:row, refund:child};
  }
  if (row.status === 'APPLIED') return {
    status:exact && nativeId(row.refundId) && String(row.refundId) === String(child.id) ?
      'APPLIED' : 'REFUND_RECONCILIATION_REQUIRED',
    adjustment:row, refund:child};
  if (exact) return {status:'REFUND_SAVED_JOURNAL_PENDING', adjustment:row, refund:child};
  return {status:['PREPARED', 'APPLYING'].includes(row.status) ? row.status : 'REFUND_RECONCILIATION_REQUIRED',
    adjustment:row, refund:null};
}

async function retainReview(loaded, observed) {
  if (!observed.adjustment) return;
  const row = observed.adjustment, input = loaded.input;
  const value = sealed({schema:REFUND_REVIEW_SCHEMA, adjustmentId:input.adjustmentId,
    inputSha256:input.sha256, reviewSha256:row.reviewSha256, observedAt:now(), adjustment:row});
  const saved = await saveFirst(join(loaded.directory, 'review-' + row.reviewSha256 + '.json'), value);
  validSeal(saved, 'WOO_REFUND_REVIEW_CHANGED');
  need(saved.inputSha256 === input.sha256 && saved.reviewSha256 === row.reviewSha256,
    'WOO_REFUND_REVIEW_CHANGED');
}

async function attemptsAt(directory) {
  const names = (await readdir(directory)).filter(name => ATTEMPT.test(name));
  const attempts = await Promise.all(names.map(async name =>
    validSeal(await readJson(join(directory, name), MAX_STATE), 'WOO_REFUND_OUTCOME_CHANGED')));
  return attempts.sort((a, b) => a.startedAt.localeCompare(b.startedAt) || a.attemptId.localeCompare(b.attemptId));
}

async function observe(config, loaded, api, phase = 'recover') {
  const attemptId = randomUUID(), startedAt = now();
  let order = null, observed = null, error = null;
  try {
    order = await api.inspectRefunds(loaded.input.orderReference);
    observed = inspectMapping(config, loaded, order);
    await retainReview(loaded, observed);
  } catch (failure) { error = safeCode(failure.code, 'WOO_REFUND_READBACK_UNAVAILABLE'); }
  const result = sealed({schema:REFUND_STATUS_SCHEMA, adjustmentId:loaded.input.adjustmentId,
    orderReference:loaded.input.orderReference, inputSha256:loaded.input.sha256, phase, attemptId,
    startedAt, completedAt:now(), status:observed?.status ?? 'REFUND_READBACK_UNAVAILABLE',
    adjustment:observed?.adjustment ?? null, refund:observed?.refund ?? null, order, error});
  await writeJson(join(loaded.directory, 'recover-' + attemptId + '.json'), result, {exclusive:true});
  return result;
}

async function dispatch(config, loaded, api, phase, body) {
  const attemptId = randomUUID(), file = join(loaded.directory, phase + '-' + attemptId + '.json');
  const start = {schema:REFUND_STATUS_SCHEMA, adjustmentId:loaded.input.adjustmentId,
    orderReference:loaded.input.orderReference, inputSha256:loaded.input.sha256, phase, attemptId,
    startedAt:now(), status:'DISPATCH_RECORDED', payload:body};
  await writeJson(file, sealed(start), {exclusive:true});
  let response = null, error = null, order = null, observed = null, readbackError = null;
  try {
    response = await (phase === 'prepare' ? api.prepareRefund(loaded.input.orderReference, body) :
      api.applyRefund(loaded.input.orderReference, body));
  } catch (failure) { error = safeCode(failure.code, 'WOO_REFUND_RESPONSE_UNAVAILABLE'); }
  try {
    order = await api.inspectRefunds(loaded.input.orderReference);
    observed = inspectMapping(config, loaded, order);
    await retainReview(loaded, observed);
  } catch (failure) { readbackError = safeCode(failure.code, 'WOO_REFUND_READBACK_UNAVAILABLE'); }
  const confirmed = observed && observed.status !== 'NOT_PREPARED';
  const rejected = response && Number.isInteger(response.httpStatus) &&
    response.httpStatus >= 400 && response.httpStatus < 500;
  const status = confirmed ? observed.status : rejected ?
    safeCode(response.response?.status, 'WOO_REFUND_REQUEST_REJECTED') :
    phase === 'prepare' ? 'PREPARE_OUTCOME_UNKNOWN' : 'APPLY_OUTCOME_UNKNOWN';
  const result = sealed({...start, completedAt:now(), status, response, error, readbackError,
    adjustment:observed?.adjustment ?? null, refund:observed?.refund ?? null, order});
  await writeJson(file, result);
  return result;
}

async function recordRead(loaded, order, observed, phase) {
  await retainReview(loaded, observed);
  const attemptId = randomUUID(), result = sealed({schema:REFUND_STATUS_SCHEMA,
    adjustmentId:loaded.input.adjustmentId, orderReference:loaded.input.orderReference,
    inputSha256:loaded.input.sha256, phase, attemptId, startedAt:now(), completedAt:now(),
    status:observed.status, adjustment:observed.adjustment, refund:observed.refund, order, error:null});
  await writeJson(join(loaded.directory, 'recover-' + attemptId + '.json'), result, {exclusive:true});
  return result;
}

export async function inspectRefunds(config, order, {client} = {}) {
  need(reference(order), 'WOO_REFUND_ORDER_REQUIRED');
  return validateRefundOrder(await (client ?? createMerchantClient(config)).inspectRefunds(order), config, order);
}

/** Each explicit prepare reads the original order first. At most one POST is
 * sent; its response is followed by a fresh GET, including after interruption. */
export async function prepareRefund(config, {adjustmentId:id, order, adjustmentsPath, wooAmount, client,
  expectedSourceSha256, expectedCurrency} = {}) {
  adjustmentId(id);
  need(reference(order), 'WOO_REFUND_ORDER_REQUIRED');
  const raw = await readBytes(absolute(adjustmentsPath), MAX_EXPORT), exported = parseJson(raw);
  need(expectedSourceSha256 === undefined || HASH.test(expectedSourceSha256) && digest(raw) === expectedSourceSha256,
    'WOO_REFUND_SOURCE_CHANGED');
  const {record} = selectRefundAdjustment(exported, id);
  const api = client ?? createMerchantClient(config);
  const before = await api.inspectRefunds(order);
  bindRefundAdjustment(exported, id, before, config, order);
  need(expectedCurrency === undefined || typeof expectedCurrency === 'string' && before.order.currency === expectedCurrency,
    'WOO_REFUND_CURRENCY_CHANGED');
  const money = wooMoney(wooAmount, before.order.priceDecimals, {positive:true});
  await workspace(config);
  const directory = await privateDirectory(refundPath(config, id));
  if (!await exists(join(directory, 'input.json'))) {
