export const INCIDENT_SOURCES_SCHEMA='stellar-forge.support-incident-sources.v1';
const MAX_CONFIG_BYTES=65_536;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
