      serviceMerchants:[...serviceMerchants.values()].sort((a,b)=>a.label.localeCompare(b.label)||a.id.localeCompare(b.id)),
      merchants:state.config.merchants.map(({id,label})=>({id,label})),filters:{q,status,merchant,kind},
