  .service-desk .service-source-grid .actions { grid-column: 1 / -1; }
  .service-desk .service-exception-row { grid-template-columns: minmax(140px, 1fr) minmax(200px, 2fr); }
  .service-desk .service-exception-row button { justify-self: start; grid-column: 1 / -1; }
}
@media (max-width: 620px) {
  .service-desk .form-grid, .service-desk .service-source-grid, .service-desk .service-edition-picker,
  .service-desk .service-week, .service-desk .service-exception-row, .service-desk .service-report-navigation { grid-template-columns: 1fr; }
  .service-desk .service-facts { grid-template-columns: 1fr; gap: 3px; }
  .service-desk .service-facts dd { margin-bottom: 9px; }
  .service-desk .service-report-entry { align-items: flex-start; flex-direction: column; }
}
@media print {
  .service-desk button, .service-desk form, .service-desk .service-report-navigation, .service-desk .service-report-pages { display: none !important; }
  .service-desk .case-table-wrap { overflow: visible; }
  .service-desk .service-incident-table { min-width: 0; }
}

// MIT. Service commitments and monthly reporting inside the original SF74 case.
