// MIT. Owner-entered terms for the original SF77 builder. Browser memory only; no network/storage.
const deliveryFields={deliveryScope:'scope',deliverables:'deliverables',acceptanceCriteria:'acceptanceCriteria'};

// Shared conversion for the original form and host-configured merchant operator.
// This keeps unfinished form values in SF74; SF77 still validates a proposal.
export function termsDocumentFromDraft(values) {
  if(!values||typeof values!=='object'||Array.isArray(values))throw new Error('Unknown owner terms draft shape.');
  const keys=['workOrderRef','sellerDisplayName','relationshipOwner','proposedWindow','consentStatus','consentReceipt',
    'priceApproval','feeUsd','costUsd','approvalReceipt',...Object.keys(deliveryFields)];
  if(Object.keys(values).some(key=>!keys.includes(key)))throw new Error('Unknown owner terms draft field.');
  const draft={...Object.fromEntries(Object.keys(deliveryFields).map(key=>[key,''])),...values};
  for(const key of keys)if(typeof draft[key]!=='string'||draft[key].length>8192)throw new Error('Invalid '+key+' draft.');
  if(!['NOT_RECORDED','CONFIRMED'].includes(draft.consentStatus)||
      !['NOT_APPROVED','OWNER_APPROVED_PROPOSAL'].includes(draft.priceApproval))throw new Error('Unknown owner terms draft status.');
  const approved=draft.priceApproval==='OWNER_APPROVED_PROPOSAL',confirmed=draft.consentStatus==='CONFIRMED';
  const costText=draft.costUsd.trim();
  if(approved)for(const key of ['feeUsd',...(costText?['costUsd']:[])])if(!/^-?(?:\d+|\d*\.\d+)(?:[eE][+-]?\d+)?$/.test(draft[key].trim())||!Number.isFinite(Number(draft[key])))
    throw new Error('Provide the recorded '+key+' value before preparing the proposal.');
  const delivery=Object.fromEntries(Object.entries(deliveryFields).map(([name,key])=>[key,draft[name].trim()]));
  return {workOrderRef:draft.workOrderRef.trim(),sellerDisplayName:draft.sellerDisplayName.trim(),
    relationshipOwner:draft.relationshipOwner.trim(),proposedWindow:draft.proposedWindow.trim()||'UNSCHEDULED',
    ...(Object.values(delivery).some(Boolean)?{delivery}:{}),
    merchantConsent:{status:draft.consentStatus,receiptUrl:confirmed?draft.consentReceipt.trim():null},
    commercial:{priceApproval:draft.priceApproval,feeUsd:approved?Number(draft.feeUsd):null,
      costUsd:approved&&costText?Number(costText):null,approvalReceiptUrl:approved?draft.approvalReceipt.trim():null}};
}

export function termsDraftFromDocument(doc) {
  const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
  if(!object(doc)||!object(doc.merchantConsent)||!object(doc.commercial))
    throw new Error('Choose a terms file with merchantConsent and commercial fields.');
  if(doc.delivery!==undefined&&(!object(doc.delivery)||Object.keys(doc.delivery).some(key=>!Object.values(deliveryFields).includes(key))))
    throw new Error('Invalid owner delivery terms.');
  if(!['NOT_RECORDED','CONFIRMED'].includes(doc.merchantConsent.status)||
      !['NOT_APPROVED','OWNER_APPROVED_PROPOSAL'].includes(doc.commercial.priceApproval))
    throw new Error('The terms file has an unknown permission or price approval status.');
  const string=(value,label,max=Infinity)=>{
    if(value===null||value===undefined)return '';
    if(typeof value!=='string'||value.length>max)throw new Error('Invalid '+label+' in the terms file.');
    return value;
  };
  const number=(value,label)=>{
    if(value===null||value===undefined)return '';
    if(typeof value!=='number'||!Number.isFinite(value))throw new Error('Invalid '+label+' in the terms file.');
    return String(value);
  };
  return {workOrderRef:string(doc.workOrderRef,'work order reference',120),sellerDisplayName:string(doc.sellerDisplayName,'seller name',200),
    relationshipOwner:string(doc.relationshipOwner,'relationship owner',200),proposedWindow:string(doc.proposedWindow,'delivery window'),
    consentStatus:doc.merchantConsent.status,consentReceipt:string(doc.merchantConsent.receiptUrl,'permission record URL'),
    priceApproval:doc.commercial.priceApproval,feeUsd:number(doc.commercial.feeUsd,'fee'),costUsd:number(doc.commercial.costUsd,'cost'),
    approvalReceipt:string(doc.commercial.approvalReceiptUrl,'owner approval record URL'),
    ...Object.fromEntries(Object.entries(deliveryFields).map(([name,key])=>[name,string(doc.delivery?.[key],key,8192)]))};
}

export function mountTermsEditor(container, {onChange=()=>{}}={}) {
  container.innerHTML=`
    <div class="form-grid">
      <label>Work order reference <small>Your reference for this proposed scope</small><input name="workOrderRef" data-label="Work order reference" required maxlength="120" autocomplete="off" placeholder="Your internal reference"></label>
      <label>Seller name <small>The actual merchant this work is for</small><input name="sellerDisplayName" data-label="Seller name" required maxlength="200" autocomplete="off" placeholder="Merchant or organization"></label>
      <label>Relationship owner <small>Person responsible for this merchant and the offer</small><input name="relationshipOwner" data-label="Relationship owner" required maxlength="200" autocomplete="off" placeholder="Owner name"></label>
      <label>Proposed delivery window <small>Optional; leave blank if no window has been agreed</small><input name="proposedWindow" data-label="Proposed delivery window" autocomplete="off" placeholder="Unscheduled"></label>
    </div>
    <h3>Work to deliver</h3>
    <p>Record the scope and criteria supplied by the owner. These entries describe the proposed work; they do not mark it complete.</p>
    <div class="form-grid">
      <label class="full">Scope and exclusions<small>The exact operation, source period and service boundary</small><textarea name="deliveryScope" data-label="Delivery scope" maxlength="8192" rows="3" placeholder="Work included and any agreed exclusions"></textarea></label>
      <label class="full">Deliverables<small>What the merchant should receive</small><textarea name="deliverables" data-label="Deliverables" maxlength="8192" rows="3" placeholder="Concrete outputs and handoff items"></textarea></label>
      <label class="full">Acceptance criteria<small>How the merchant and operator will review the result</small><textarea name="acceptanceCriteria" data-label="Acceptance criteria" maxlength="8192" rows="3" placeholder="Observable completion criteria and agreed review"></textarea></label>
    </div>
    <h3>Existing seller permission</h3>
    <p>Select what is already recorded for this merchant. Preparing a work order does not obtain permission or send an offer.</p>
    <div class="form-grid">
      <label>Permission status <select name="consentStatus" data-label="Permission status"><option value="NOT_RECORDED">Not recorded</option><option value="CONFIRMED">Confirmed in an existing record</option></select></label>
      <label data-consent-receipt hidden>Permission record URL <small>Existing HTTPS record supplied by the relationship owner</small><input name="consentReceipt" data-label="Permission record URL" type="url" pattern="https://.+" autocomplete="off" placeholder="https://…" disabled></label>
    </div>
    <h3>Owner-approved proposal</h3>
    <p>A proposed price is separate from the seller accepting the work. Record approval when the commercial owner supplies the proposal price and approval record. Delivery cost is optional when it has not been recorded.</p>
    <div class="form-grid">
      <label class="full">Price approval <select name="priceApproval" data-label="Price approval"><option value="NOT_APPROVED">Not approved — withhold price from the packet</option><option value="OWNER_APPROVED_PROPOSAL">Proposal already approved by the owner</option></select></label>
      <label data-approved-price hidden>Approved fee · USD <small>Price proposed to the seller</small><input name="feeUsd" data-label="Approved fee" type="number" min="0.01" step="0.01" inputmode="decimal" autocomplete="off" placeholder="0.00" disabled></label>
      <label data-approved-price hidden>Recorded delivery cost · USD <small>Optional. Leave blank when unknown; enter 0 only for a recorded zero cost.</small><input name="costUsd" data-label="Recorded delivery cost" type="number" min="0" step="0.01" inputmode="decimal" autocomplete="off" placeholder="0.00" disabled></label>
      <label data-approved-price class="full" hidden>Owner approval record URL <small>Existing HTTPS record approving the proposal price</small><input name="approvalReceipt" data-label="Owner approval record URL" type="url" pattern="https://.+" autocomplete="off" placeholder="https://…" disabled></label>
    </div>
    <p data-terms-summary class="hint" aria-live="polite"></p>
    `;
  const fields=Object.fromEntries([...container.querySelectorAll('[name]')].map(el=>[el.name,el]));
  function showFields(selector,visible) {
    for(const label of container.querySelectorAll(selector)) {
      label.hidden=!visible;
      const input=label.querySelector('input');input.disabled=!visible;input.required=visible&&input.name!=='costUsd';
    }
  }
  function sync() {
    const consent=fields.consentStatus.value==='CONFIRMED';
    const approved=fields.priceApproval.value==='OWNER_APPROVED_PROPOSAL';
    showFields('[data-consent-receipt]',consent);showFields('[data-approved-price]',approved);
    let summary='The packet will withhold price. You can still prepare the workorder from its original sources.';
    if(approved) {
      summary='The packet will include the owner-approved proposal. Seller acceptance stays open.';
      const costText=fields.costUsd.value.trim(),fee=Number(fields.feeUsd.value),cost=costText?Number(costText):null;
      if(cost===null)summary+=' Delivery cost is not recorded; margin is unknown.';
      else if(Number.isFinite(fee)&&fee>0&&Number.isFinite(cost)&&cost>=0) {
        const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(value);
        summary+=' Recorded delivery cost: '+money(cost)+'. Margin before other costs: '+((fee-cost)/fee*100).toFixed(2)+'%.';
        if(cost>fee)summary+=' Recorded cost exceeds the approved fee by '+money(cost-fee)+'. The approved fee stays unchanged.';
      }
    }
    container.querySelector('[data-terms-summary]').textContent=summary;
  }
  function read() {
    sync();
    for(const field of Object.values(fields)) {
      if(field.required&&!field.disabled&&!field.value.trim())throw new Error('Provide '+field.dataset.label.toLowerCase()+'.');
      if(!field.checkValidity()) {field.reportValidity();throw new Error('Check '+field.dataset.label.toLowerCase()+'.');}
    }
    return termsDocumentFromDraft(Object.fromEntries(Object.entries(fields).map(([name,field])=>[name,field.value])));
  }

  function load(terms) {
    // Validate the complete shape before replacing fields; a failed import leaves current terms intact.
    const values=termsDraftFromDocument(terms);
    for(const [name,value] of Object.entries(values))fields[name].value=value;
    sync();onChange();
  }
  // Case files must also preserve incomplete and currently hidden form entries.
  // These are raw drafts, not a validated SF77 proposal or an approval decision.
  function readDraft() {
    return validateDraft(Object.fromEntries(Object.entries(fields).map(([name,field])=>[name,field.value])));
  }
  function validateDraft(values) {
    if(!values||typeof values!=='object'||Array.isArray(values)||
        Object.keys(values).some(name=>!Object.hasOwn(fields,name)))
      throw new Error('Unknown owner terms draft shape.');
    // Earlier original cases have no delivery fields; their existing raw entries stay intact.
    const normalized={...values};
    for(const name of Object.keys(deliveryFields))if(!Object.hasOwn(normalized,name))normalized[name]='';
    for(const [name,field] of Object.entries(fields)) {
      const value=normalized[name];
      if(typeof value!=='string'||value.length>8192||
          (field.maxLength>0&&value.length>field.maxLength))
        throw new Error('Invalid '+field.dataset.label+' draft.');
      // Preserve browser-native values exactly, including select and number semantics.
      const probe=field.cloneNode(true);probe.value=value;
      if(probe.value!==value)throw new Error('Unrepresentable '+field.dataset.label+' draft.');
    }
    return normalized;
  }
  function loadDraft(values) {
    const normalized=validateDraft(values);
    for(const [name,value] of Object.entries(normalized))fields[name].value=value;
    sync();onChange();
  }
  container.addEventListener('input',()=>{sync();onChange();});
  container.addEventListener('change',()=>{sync();onChange();});
  sync();
  return {read,load,readDraft,validateDraft,loadDraft};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {createHash} from 'node:crypto';
import {start} from '../server.mjs';
import {evaluate} from '../../sf72-post-only-preflight/preflight.mjs';

const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const encode = bytes => Buffer.from(bytes).toString('base64');
const bytesOf = report => Buffer.from(JSON.stringify(report, null, 2).replace(/\n/g, '\r\n') + '\r\n');
const close = server => new Promise(resolve => {server.close(resolve); server.closeAllConnections();});

test('existing console connects original GET and POST captures to original SF76 offline comparison', async t => {
  let ready = false, method = 'GET', requests = 0;
  const buyerOrigin = 'http://127.0.0.1:1';
  const merchant = createServer((req, res) => {
    requests++;
    const origin = `http://127.0.0.1:${merchant.address().port}`;
    const offer = {resource: {url: origin + '/paid'}, type: 'http', x402Version: 2,
      accepts: [{network: 'stellar:testnet', scheme: 'exact', payTo: 'PUBLIC_TEST_RECIPIENT', amount: '1', asset: 'TEST'}],
      extensions: {bazaar: {info: {input: {type: 'http', method}}}}};
    if (req.url.startsWith('/discovery/resources')) {
      res.writeHead(200, {'content-type': 'application/json'});
      res.end(JSON.stringify({items: [offer], pagination: {total: 1}})); return;
    }
    if (ready) {
      res.setHeader('access-control-allow-origin', buyerOrigin);
      res.setHeader('access-control-expose-headers', 'payment-required');
      res.setHeader('access-control-allow-methods', 'GET, POST');
      res.setHeader('access-control-allow-headers', 'payment-signature, content-type');
    }
    if (req.method === 'OPTIONS') {res.writeHead(204); res.end(); return;}
    assert.equal(req.method, 'GET', 'fixture must not receive a paid operation');
    res.writeHead(402, {'payment-required': encode(JSON.stringify(offer))}); res.end();
  });
  await new Promise(resolve => merchant.listen(0, '127.0.0.1', resolve));
  t.after(() => close(merchant));
  const {server, url} = await start({allowLoopback: true});
  t.after(() => close(server));
  const consoleOrigin = new URL(url).origin;
  const merchantOrigin = `http://127.0.0.1:${merchant.address().port}`;
  const api = async (path, input, origin = consoleOrigin) => {
    const response = await fetch(new URL(path, url), {method: 'POST',
      headers: {'content-type': 'application/json', ...(origin ? {origin} : {})}, body: JSON.stringify(input)});
    return {status: response.status, body: await response.json()};
  };
  const intake = async () => {
    const result = await api('/api/intake', {resource: merchantOrigin + '/paid',
      catalog: merchantOrigin + '/discovery/resources', origin: buyerOrigin,
      network: 'stellar:testnet', payTo: 'PUBLIC_TEST_RECIPIENT', method, permission: true});
    assert.equal(result.status, 200); return result.body.report;
  };

  const before = await intake();
  ready = true;
  const after = await intake();
  const beforeBytes = bytesOf(before), afterBytes = bytesOf(after);
  const pair = {before: encode(beforeBytes), after: encode(afterBytes)};
  const requestCount = requests;
  const result = await api('/api/compare', pair);
  assert.equal(result.status, 200);
  assert.equal(result.body.report.classification, 'GET_UNPAID_DISCOVERY_AND_BROWSER_READY');
  assert.equal(result.body.report.source.before.sha256, hash(beforeBytes));
  assert.equal(result.body.report.source.after.sha256, hash(afterBytes));
  assert.ok(result.body.report.changes.notReobservedWithCompleteAfterCatalog.length > 0);
  assert.equal(requests, requestCount, 'comparison must not call any merchant/provider endpoint');

  for (const origin of [undefined, 'https://unrelated.example']) {
    assert.equal((await api('/api/compare', pair, origin === undefined ? null : origin)).status, 403);
  }
  assert.equal((await api('/api/compare', {...pair, before: pair.before + '\n'})).status, 422);
  assert.equal((await api('/api/compare', {...pair, postAfter: encode('{}')})).status, 422);
  const different = structuredClone(after); different.scope.resource += '/different';
  assert.equal((await api('/api/compare', {...pair, after: encode(bytesOf(different))})).status, 422);
  const tampered = structuredClone(before); tampered.findings = []; tampered.state = 'UNPAID_DISCOVERY_AND_BROWSER_READY';
  assert.equal((await api('/api/compare', {...pair, before: encode(bytesOf(tampered))})).status, 422);
  assert.equal((await api('/api/compare', {...pair, before: encode(Buffer.alloc(2_000_001, 32))})).status, 422);

  method = 'POST'; ready = false;
  const postBefore = await intake(), postBeforeBytes = bytesOf(postBefore);
  const pb = await evaluate(postBefore, {allowLoopback: true}); pb.source.intakeSha256 = hash(postBeforeBytes);
  ready = true;
  const postAfter = await intake(), postAfterBytes = bytesOf(postAfter);
  const pa = await evaluate(postAfter, {allowLoopback: true}); pa.source.intakeSha256 = hash(postAfterBytes);
  const postPair = {before: encode(postBeforeBytes), after: encode(postAfterBytes),
    postBefore: encode(bytesOf(pb)), postAfter: encode(bytesOf(pa))};
  const postRequestCount = requests;
  const postResult = await api('/api/compare', postPair);
  assert.equal(postResult.status, 200);
  assert.equal(postResult.body.report.classification, 'POST_OPTIONS_READY_CHALLENGE_UNCHECKED');
  assert.equal(postResult.body.report.source.sf72After.reportSha256, hash(bytesOf(pa)));
  assert.equal(requests, postRequestCount);
  // Semantically identical JSON with different bytes must not satisfy the original SF72 binding.
  assert.equal((await api('/api/compare', {...postPair, before: encode(JSON.stringify(postBefore))})).status, 422);
  assert.equal(requests, postRequestCount);

  const page = await fetch(url);
  assert.match(await page.text(), /id="compare-form"/);
  assert.equal(page.headers.get('cache-control'), 'no-store, max-age=0');
  assert.equal((await fetch(new URL('/console.mjs', url))).status, 200);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {createHash} from 'node:crypto';
import {start} from '../server.mjs';
import {combine} from '../../sf70-merchant-intake/run.mjs';
import {compare} from '../../sf76-merchant-remediation-delta/compare.mjs';
import {evaluate} from '../../sf72-post-only-preflight/preflight.mjs';

const sha = report => createHash('sha256').update(JSON.stringify(report)).digest('hex');
const delta = (before, after, extra={}) => compare({before, after, beforeSha:sha(before), afterSha:sha(after), ...extra});
const close = server => new Promise(resolve => {server.close(resolve); server.closeAllConnections();});

test('console credential policy reaches native CORS and remains immutable in repair comparisons', async t => {
  let credentialSupport=false, method='GET', requests=0;
  const origin='http://127.0.0.1:1';
  const merchant=createServer((req,res)=>{
    requests++;
    const resource=`http://127.0.0.1:${merchant.address().port}/paid`;
    const offer={resource:{url:resource},type:'http',x402Version:2,
      accepts:[{network:'stellar:testnet',scheme:'exact',payTo:'PUBLIC_TEST_RECIPIENT',amount:'1',asset:'TEST'}],
      extensions:{bazaar:{info:{input:{type:'http',method}}}}};
    if (req.url.startsWith('/discovery/resources')) {
      res.writeHead(200,{'content-type':'application/json'});
      res.end(JSON.stringify({items:[offer],pagination:{total:1}}));return;
    }
    res.setHeader('access-control-allow-origin',credentialSupport?origin:'*');
    if (credentialSupport) res.setHeader('access-control-allow-credentials','true');
    res.setHeader('access-control-expose-headers','payment-required');
    res.setHeader('access-control-allow-methods','GET, POST');
    res.setHeader('access-control-allow-headers','payment-signature, content-type');
    if (req.method==='OPTIONS') {res.writeHead(204);res.end();return;}
    assert.equal(req.method,'GET');
    assert.equal(req.headers.cookie,undefined);
    assert.equal(req.headers.authorization,undefined);
    res.writeHead(402,{'payment-required':Buffer.from(JSON.stringify(offer)).toString('base64')});res.end();
  });
  await new Promise(resolve=>merchant.listen(0,'127.0.0.1',resolve));t.after(()=>close(merchant));
  const {server,url}=await start({allowLoopback:true});t.after(()=>close(server));
  const base=`http://127.0.0.1:${merchant.address().port}`;
  const intake=async credentialed=>{
    const payload={resource:base+'/paid',catalog:base+'/discovery/resources',origin,
      network:'stellar:testnet',payTo:'PUBLIC_TEST_RECIPIENT',method,permission:true};
    if (credentialed!==undefined) payload.credentialed=credentialed;
    const response=await fetch(new URL('/api/intake',url),{method:'POST',
      headers:{origin:new URL(url).origin,'content-type':'application/json'},body:JSON.stringify(payload)});
    return {status:response.status,...await response.json()};
  };
  const anonymous=await intake();assert.equal(anonymous.status,200);
  assert.equal(anonymous.report.scope.browserCredentialed,false);
  assert.equal(anonymous.report.state,'UNPAID_DISCOVERY_AND_BROWSER_READY');
  const before=await intake(true);assert.equal(before.status,200);
  assert.equal(before.report.scope.browserCredentialed,true);
  assert.equal(before.report.originals.browserReadiness.credentialed,true);
  assert.equal(before.report.state,'REMEDIATION_REQUIRED');
  const requestCount=requests;
  assert.equal((await intake('true')).status,422);
  assert.equal(requests,requestCount);
  assert.throws(()=>delta(anonymous.report,before.report),/browserCredentialed/);
  credentialSupport=true;
  const after=await intake(true);assert.equal(after.report.state,'UNPAID_DISCOVERY_AND_BROWSER_READY');
  assert.equal(delta(before.report,after.report).technicalMilestoneObserved,true);
  const legacyBefore=structuredClone(before.report),legacyAfter=structuredClone(after.report);
  delete legacyBefore.scope.browserCredentialed;delete legacyAfter.scope.browserCredentialed;
  assert.equal(delta(legacyBefore,legacyAfter).scope.browserCredentialed,true);
  const wrong=structuredClone(after.report);wrong.scope.browserCredentialed=false;
  assert.throws(()=>delta(before.report,wrong),/disagree about browser credential mode/);
  const unknown=combine({seller:before.report.originals.sellerCatalog,browser:null,error:'Original browser unavailable',
    config:{resourceUrl:base+'/paid',catalogUrl:base+'/discovery/resources',origin,
      network:'stellar:testnet',payTo:'PUBLIC_TEST_RECIPIENT',method},observedAt:before.report.observedAt});
  delete unknown.scope.browserCredentialed;
  const incomplete=delta(unknown,legacyAfter);
  assert.equal(incomplete.classification,'BROWSER_CREDENTIAL_MODE_UNCONFIRMED');
  assert.equal(incomplete.technicalMilestoneObserved,false);
  assert.deepEqual(incomplete.changes.notReobservedWithCompleteAfterCatalog,[]);
  assert.ok(incomplete.changes.notReobservedButCredentialModeUnknown.length>0);

  method='POST';
