      entries,interrupted:signal?.aborted===true,
      recordAuthority:'ORIGINAL_SF36_LEDGER; PER-PAGE VIEWS ARE SAVED BESIDE THE ORIGINAL ATTEMPT'};
  } finally {await release();}
}
