        checkedAt:now(),processProof:checked.proof,originalLedgerCheck,
        ...(plan.executionRuntime === undefined ? {} : { executionRuntime: plan.executionRuntime })};
      const checksDirectory=join(current.directory,'checks');
      await privateDirectory(checksDirectory);
      await writeJson(join(checksDirectory,digest(jsonBytes(executionCheck))+'.json'),executionCheck,{exclusive:true});
      return executionCheck;
    },
  },async({history,originalVerification})=>{
    const current=await chain(operation);
    need(current.pending?.planSha256===expectedPlanSha256 && history.status==='RETAINED',
      'PREAPPROVAL_PREPARED_PLAN_REQUIRED');
    const {meta,config}=current;
    let command={args:['--execute','--config',operation.configPath],entryFile:runtime.cli};
    if(meta.nativeWorkspace)command=workspaceCommand({...operation.buyer,runtime},{
      directory:meta.nativeWorkspace,configPath:operation.configPath,ticketSha256:meta.ticketSha256??null});
    const checkSha256=digest(jsonBytes(originalVerification));
  const reservation = plan.sources.find(value => value.name === 'download-reservation.json');
  if (reservation?.exists) {
    const released = join(current.directory, 'released-download-reservation.json');
    if (await exists(released)) {
      const observed = await snapshot(reservation.name, released, { limit: 16384 });
      need(observed.sha256 === reservation.sha256 && observed.device === reservation.device &&
        observed.inode === reservation.inode && !await exists(reservation.path),
      'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
    } else {
      const observed = await snapshot(reservation.name, reservation.path, { limit: 16384 });
      need(observed.sha256 === reservation.sha256 && observed.device === reservation.device &&
        observed.inode === reservation.inode, 'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
      try { await rename(reservation.path, released); }
      catch (error) {
        if (error.code !== 'ENOENT') throw error;
        const moved = await snapshot(reservation.name, released, { limit: 16384 });
        need(moved.sha256 === reservation.sha256 && moved.device === reservation.device &&
          moved.inode === reservation.inode, 'PREAPPROVAL_DOWNLOAD_RESERVATION_CHANGED');
      }
      await syncDirectory(dirname(reservation.path)); await syncDirectory(current.directory);
    }
  }
  await verifySources(plan);
  checkSignal(signal);
  const createdAt = now();
  let attempt = { schema: NODE_SCHEMA, intentId: operation.intentId, state: 'STARTING',
    createdAt, startedAt: createdAt, executionCheckSha256: checkSha256,
    configSha256: meta.configSha256, bodySha256: meta.bodySha256, retry: 'NO_AUTOMATIC_RETRY',
    preapprovalRecovery: { planSha256: expectedPlanSha256, sourceAttemptSha256: plan.sourceAttemptSha256,
      wireSelectionSha256:history.selectionSha256,wireRetirementSha256:history.retirementSha256 },
    ...(plan.executionRuntime === undefined ? {} : { executionRuntime: plan.executionRuntime }),
  };
  const attemptPath = join(current.directory, 'attempt.json');
  const reservations = await prepareWriteReservations([
    { path: attemptPath, bytes: attemptRecordLimit, exclusive: true },
    { path: attemptPath, bytes: attemptRecordLimit },
    { path: attemptPath, bytes: attemptRecordLimit },
    { path: attemptPath, bytes: attemptRecordLimit },
    { path: join(current.directory, 'result.json'),
      bytes: resultRecordLimit(runtime), exclusive: true },
  ], { reserveFile, signal });
  const recordAttempt = async () => {
    try { await writeJson(attemptPath, attempt, { exclusive: true }); }
    catch (error) {
      if (error.code === 'EEXIST') throw new BuyerError('ATTEMPT_ALREADY_RECORDED_USE_RECOVER', { operation });
      throw error;
    }
    let run;
    try {
      run = await runtime.run(command.args, {
        directory: current.directory, signal, entryFile: command.entryFile,
        beforeSpawn: async nativeCommand => {
          await verifySources(plan);
          const retainedWire=await selectedWireHistory(operation,current,selected);
          need(retainedWire?.retirementSha256===history.retirementSha256,
            'PREAPPROVAL_WIRE_RETIREMENT_CHANGED');
          if (plan.executionRuntime !== undefined)
            await verifySuccessorRuntimeSource(plan.executionRuntime.runtimeSource, { signal });
          attempt = { ...attempt, nativeCommand };
          await writeJson(attemptPath, attempt);
        },
        started: async (pid, processIdentity) => {
          attempt = { ...attempt, state: 'STARTED', pid, startedAt: now(),
            ...(processIdentity ? { processIdentity } : {}) };
          await writeJson(attemptPath, attempt);
        },
      });
    } catch (error) {
      await writeJson(attemptPath, unstartedAttempt(attempt, error) ??
        { ...attempt, state: 'INTERRUPTED_OR_START_FAILED', endedAt: now() });
      throw error;
    }
    if (run.output?.mode !== NATIVE_RESULT || run.output.intentId !== operation.intentId) {
      await writeJson(attemptPath, unstartedAttempt(attempt, run) ??
        { ...attempt, state: 'NATIVE_RESULT_UNAVAILABLE', endedAt: now(),
          exitCode: run.exitCode, errorCode: run.errorCode ?? 'NATIVE_RESULT_INVALID' });
      throw new BuyerError(run.errorCode ?? 'NATIVE_RESULT_INVALID', { operation, exitCode: run.exitCode });
    }
    const record = { schema: NODE_SCHEMA, intentId: operation.intentId, configSha256: meta.configSha256,
      native: run.output, exitCode: run.exitCode, exitSignal: run.exitSignal,
      runtimeError: run.errorCode, recovered: false, recordedAt: now(),
      preapprovalRecovery: { directory: current.directory, planSha256: expectedPlanSha256,
        sourceAttemptSha256: plan.sourceAttemptSha256 },
      ...(plan.executionRuntime === undefined ? {} : { executionRuntime: plan.executionRuntime }),
    };
    await writeJson(join(current.directory, 'result.json'), record, { exclusive: true });
    await writeJson(attemptPath, { ...attempt, state: 'RECORDED', exitCode: run.exitCode, endedAt: now() });
    return operation._result(record);
  };
  try { return reservations ? await reservations.run(recordAttempt) : await recordAttempt(); }
  finally { await reservations?.close(); }

  });
}

export async function recoverPreapprovalResult(operation) {
  const current = await chain(operation);
  if (!current.history.length || !current.attempt) return null;
  if (await exists(join(current.directory, 'result.json')))
    return operation._result(await readJson(join(current.directory, 'result.json'), resultRecordLimit(operation.buyer.runtime)));
  let native;
  try { native = await readJson(join(current.directory, 'stdout.json'), operation.buyer.runtime.outputLimit); }
  catch (error) { if (['ENOENT', 'JSON_INVALID'].includes(error.code)) return null; throw error; }
  if (native.mode !== NATIVE_RESULT || native.intentId !== operation.intentId) return null;
  return operation._result({ schema: NODE_SCHEMA, intentId: operation.intentId,
    configSha256: current.meta.configSha256, native, exitCode: null, exitSignal: null,
    runtimeError: 'PROCESS_EXIT_NOT_RECORDED', recovered: true, recordedAt: now(),
    preapprovalRecovery: { directory: current.directory, planSha256: current.history.at(-1).planSha256 },
    ...(current.history.at(-1).plan.executionRuntime === undefined ? {} :
      { executionRuntime: current.history.at(-1).plan.executionRuntime }),
  });
}

// MIT. Capture an actual Linux child identity once, at native launch.
// PID alone never authorizes recovery. Missing or raced observations stay explicit.
import { readFile, readlink, readdir, stat } from 'node:fs/promises';

const SCHEMA = 'stellar-forge.node-process-identity.v1';
const vanished = error => ['ENOENT', 'ESRCH'].includes(error?.code);

function procStat(raw) {
  const close = raw.lastIndexOf(')');
  if (close < 1) throw new Error('PROCESS_STAT_INVALID');
  const pid = Number(raw.slice(0, raw.indexOf(' ')));
  const fields = raw.slice(close + 2).trim().split(/\s+/);
  if (!Number.isSafeInteger(pid) || pid < 1 || fields.length < 20 ||
      !/^\d+$/.test(fields[19]) || !/^\d+$/.test(fields[1]))
    throw new Error('PROCESS_STAT_INVALID');
  return { procPid: pid, parentProcPid: Number(fields[1]), startTicks: fields[19] };
}

async function sample(procPid) {
  const base = '/proc/' + procPid;
  const before = procStat(await readFile(base + '/stat', 'utf8'));
  const [namespace, status] = await Promise.all([
    readlink(base + '/ns/pid'), readFile(base + '/status', 'utf8'),
  ]);
  const match = /^NSpid:\s+([0-9 \t]+)$/m.exec(status);
  if (!match || !/^pid:\[\d+\]$/.test(namespace)) throw new Error('PROCESS_NAMESPACE_UNAVAILABLE');
  const namespacePids = match[1].trim().split(/\s+/).map(Number);
  const after = procStat(await readFile(base + '/stat', 'utf8'));
  if (before.procPid !== after.procPid || before.startTicks !== after.startTicks ||
      before.parentProcPid !== after.parentProcPid)
    throw new Error('PROCESS_IDENTITY_CHANGED');
  return { ...after, namespace, namespacePids };
}

export async function captureChildProcessIdentity(pid) {
  const unavailable = reason => ({ schema: SCHEMA, status: 'UNAVAILABLE', pid, reason });
  if (process.platform !== 'linux') return unavailable('LINUX_PROCESS_IDENTITY_UNAVAILABLE');
  if (!Number.isSafeInteger(pid) || pid < 1) return unavailable('CHILD_PID_INVALID');
  try {
    const procfsDevice = (await stat('/proc', { bigint: true })).dev.toString();
    const bootId = (await readFile('/proc/sys/kernel/random/boot_id', 'utf8')).trim();
    if (!/^[a-f0-9-]{36}$/.test(bootId)) return unavailable('BOOT_ID_UNAVAILABLE');
    const ownStat = procStat(await readFile('/proc/self/stat', 'utf8'));
    const ownNamespace = await readlink('/proc/self/ns/pid');
    const own = await sample(ownStat.procPid);
    const matches = candidate => candidate.namespace === ownNamespace &&
      candidate.namespacePids.at(-1) === pid && candidate.parentProcPid === own.procPid;
    const childCandidate = async procPid => {
      // A container PID may name an unrelated host process in this procfs.
      // Establish parent ownership before following a namespace link.
      const candidate = procStat(await readFile('/proc/' + procPid + '/stat', 'utf8'));
      if (candidate.parentProcPid !== own.procPid) return null;
      return sample(procPid);
    };
    let child = null;
    try { const direct = await childCandidate(pid); if (direct && matches(direct)) child = direct; }
    catch (error) { if (!vanished(error)) throw error; }
    if (!child) {
      // A container may expose a parent namespace's procfs. Resolve the child's
      // actual NSpid and namespace once, rather than treating an aliased PID as it.
      const entries = (await readdir('/proc')).filter(name => /^[1-9]\d*$/.test(name));
      if (entries.length > 131072) return unavailable('PROCESS_TABLE_LIMIT');
      for (const name of entries) {
        let candidate;
        try { candidate = await childCandidate(Number(name)); }
        catch (error) { if (vanished(error)) continue; throw error; }
        if (!candidate || !matches(candidate)) continue;
        if (child) return unavailable('CHILD_IDENTITY_AMBIGUOUS');
        child = candidate;
      }
    }
    if (!child) return unavailable('CHILD_ENDED_BEFORE_IDENTITY_CAPTURE');
    const checked = await sample(child.procPid);
    const parent = await sample(own.procPid);
    if (!matches(checked) || checked.startTicks !== child.startTicks ||
        parent.startTicks !== own.startTicks ||
        (await stat('/proc', { bigint: true })).dev.toString() !== procfsDevice ||
        (await readFile('/proc/sys/kernel/random/boot_id', 'utf8')).trim() !== bootId)
      return unavailable('PROCESS_IDENTITY_CHANGED');
    return {
      schema: SCHEMA, status: 'RECORDED', pid, procPid: checked.procPid,
      startTicks: checked.startTicks, namespace: checked.namespace, bootId, procfsDevice,
      parent: { procPid: parent.procPid, startTicks: parent.startTicks, namespace: parent.namespace },
      capturedAt: new Date().toISOString(),
    };
  } catch (error) {
    return unavailable(vanished(error) ? 'CHILD_ENDED_BEFORE_IDENTITY_CAPTURE' : 'PROCESS_IDENTITY_NOT_OBSERVED');
  }
}

