  if(!first) throw firstError??new InputError('DISCOVERY_ACCEPT_NOT_FOUND');
  if(acceptIndex!==undefined) {
    need(Number.isSafeInteger(acceptIndex)&&acceptIndex>=0,'EXPLICIT_SELECTION_INDEX_REQUIRED');
