          !Number.isSafeInteger(part.bytes)||part.bytes<1||part.bytes>PART_BYTES||
          index<value.parts.length-1&&part.bytes!==PART_BYTES)throw fail('RECEIPT_CHANGED','The complete archive parts are invalid.');
