      Number.isSafeInteger(Number(file.bytes))&&Number(file.bytes)<=SOURCE_ARCHIVE_LIMITS.fileBytes&&SHA.test(file.sha256),'SF49_ARCHIVE_FILE_PIN_INVALID');
    total+=Number(file.bytes);names.add(file.path);
