  ensure(request.length<=SOURCE_ARCHIVE_LIMITS.metadataBytes,'SF49_ARCHIVE_METADATA_LIMIT');
  if(signal?.aborted)throw problem('SF49_ARCHIVE_ABORTED','The original archive operation was cancelled.',409);
