    try {child=spawn(python,['-B',NATIVE],{env:environment,stdio:['pipe','pipe','pipe'],shell:false});}
    catch(error){reject(error);return;}
    signal?.addEventListener('abort',abort,{once:true});
    child.on('error',error=>{spawnError=error;});
